window.LERNDATEN={"decks": [{"id": "v", "name": "Puls und Blutdruck", "sub": "CE 3.2 A: Vitalzeichen kontrollieren"}, {"id": "w", "name": "Fachwörter", "sub": "Lateinisch und Griechisch auf Deutsch"}, {"id": "s", "name": "Berufliches Selbstverständnis", "sub": "Pflege-Charta, ICN-Kodex, Kompetenzen, Maslow"}, {"id": "l", "name": "Lernen lernen", "sub": "CE 1.2: Gedächtnis, Motivation, Lerntypen"}, {"id": "k", "name": "Kommunikation und Belastung", "sub": "Kommunikationsmodelle, Ethik, Stress und Burnout"}, {"id": "f", "name": "Fälle 1 bis 6", "sub": "Fragenkatalog zu den Pflege-Fällen zum Auswendiglernen"}, {"id": "h", "name": "Hygiene", "sub": "CE 4.2 A: Erreger, Infektion, Standardhygiene, Händedesinfektion"}, {"id": "m", "name": "Mobilität und Prophylaxen", "sub": "CE 2.1: Bewegungsapparat, Immobilität, Dekubitus, Thrombose"}, {"id": "p", "name": "Körperpflege, Haut und Mund", "sub": "CE 2.2: Haut, Körperpflege, Intimpflege, Mundpflege, Prophylaxen"}], "cards": [{"id": "K000", "deck": "v", "q": "Was ist der Puls? (lat. Pulsus)", "a": "Pulsus = Schlag / Stoß.\nDruck- und Volumenschwankung durch den Blutausstoß des Herzens während der Systole. Es entstehen Druckwellen, die ins arterielle Gefäßsystem gelangen.", "kw": "Schlag; Stoß|stoss; Druck; Volumen; Herz; Systole; Arterien|arteri"}, {"id": "K001", "deck": "v", "q": "Wo wird der Puls zentral gemessen?", "a": "A. carotis (Halsschlagader)\nA. femoralis (Leistenarterie)", "kw": "carotis; Halsschlagader|hals; femoralis; Leistenarterie|leiste"}, {"id": "K002", "deck": "v", "q": "Welche peripheren Pulsmessorte gibt es?", "a": "• A. temporalis (Schläfenarterie)\n• A. brachialis (Oberarmarterie)\n• A. radialis (Speichenarterie)\n• A. ulnaris (Ellenarterie)\n• A. poplitea (Kniekehlenarterie)\n• A. tibialis posterior (hintere Schienbeinarterie)\n• A. dorsalis pedis (Fußrückenarterie)", "kw": "temporalis; brachialis; radialis; ulnaris; poplitea; tibialis; dorsalis"}, {"id": "K003", "deck": "v", "q": "Wie lässt sich der Puls bestimmen?", "a": "Manuell (mit den Fingern, z. B. an der A. radialis) oder elektronisch (z. B. mit einem Pulsoximeter am Finger).", "kw": "manuell; elektronisch|elektron; Finger"}, {"id": "K004", "deck": "v", "q": "Wie misst du den Puls manuell? (Ablauf)", "a": "1. Pflegeempfänger sollte vorher ca. 15 Minuten Ruhe haben, damit keine falsch hohen Werte entstehen.\n2. Sitzen oder liegen, Unterarm mit leicht gebeugtem Handgelenk lagern.\n3. Kuppen von Zeige-, Mittel- und Ringfinger an die A. radialis legen (Daumenseite des Handgelenks) und leicht drücken.\n4. Mit Sekundenzeiger 1 Minute zählen – oder 15 Sekunden zählen und mal 4 rechnen.\n5. Auf Pulsqualität und Rhythmus achten.\n6. Werte dokumentieren, Pflegefachkraft informieren.", "kw": "Ruhe; radialis; Zeigefinger|zeige; Mittelfinger|mittel; Ringfinger|ring; Minute|minute; mal vier|vier/4; Rhythmus; dokumentieren|dokument"}, {"id": "K005", "deck": "v", "q": "Wann wird der Puls gemessen? (Indikationen)", "a": "• Ausgangswert nicht im Normbereich\n• Veränderung anderer Vitalzeichen (Blutdruck, Atmung, Temperatur)\n• Vor der Mobilisation\n• Nach Unfällen, bei Blut- und Flüssigkeitsverlusten, im Schockzustand\n• Bei Aufnahme und regelmäßig im Krankenhausaufenthalt\n• Vor, während und nach Operationen\n• Bei Herz-/Kreislauf- und Lungenerkrankungen, Fieber, Vergiftungen\n• Bei kreislaufwirksamen Medikamenten und vor/nach kreislaufbelastenden Tätigkeiten\n• „Wenn etwas nicht stimmt“ (Unwohlsein)", "kw": "Mobilisation|mobilis; Schock|schock; Operation|operation; Aufnahme|aufnahme; Medikamente|medikament; Fieber|fieber; Unwohlsein|unwohl"}, {"id": "K006", "deck": "v", "q": "Was ist der Blutdruck?", "a": "Kraft, die das Blut auf die Gefäßwand der Arterien und Venen ausübt.\nGemessen wird in der Einheit mmHg (Millimeter Quecksilbersäule).", "kw": "Kraft; Blut; Gefäßwand|gefass; Arterien|arteri; Venen|vene; mmHg|mmhg/millimeter; Quecksilber"}, {"id": "K007", "deck": "v", "q": "Systolisch und diastolisch – was ist was?", "a": "Entsprechend der Herzaktivität:\n• systolischer Blutdruck = oberer Wert = Systole = Auswurfphase\n• diastolischer Blutdruck = unterer Wert = Diastole = Erschlaffungsphase\nBeispiel 120/80 mmHg: 120 systolisch, 80 diastolisch. Beide Werte werden in mmHg angegeben.", "kw": "systolisch|systol; oberer; Auswurfphase|auswurf; diastolisch|diastol; unterer; Erschlaffungsphase|erschlaff; 120; 80"}, {"id": "K008", "deck": "v", "q": "Aus welchen Teilen besteht ein Blutdruckmessgerät?", "a": "Manschette (am Oberarm) · Aufblasballon · Ventil · Manometer (Druckanzeige) · Stethoskop (zum Abhören)", "kw": "Manschette; Aufblasballon|ballon; Ventil; Manometer; Stethoskop"}, {"id": "K009", "deck": "v", "q": "Wann wird der Blutdruck gemessen? (Indikationen)", "a": "• Bei Neuaufnahmen und bei Herz-/Kreislauferkrankungen\n• Regelmäßig während des Krankenhausaufenthalts bzw. nach Versorgungsauftrag\n• Vor, während und nach Operationen\n• Vor der Mobilisation\n• Bei bekannter Hyper- oder Hypotonie\n• Bei Kreislaufkollaps = akute Hypotonie\n• Bei Gabe blutdruckbeeinflussender Medikamente\n• Bei starken Blutdruckschwankungen\n• Nach Unfällen, bei Blut-/Flüssigkeitsverlusten und bei Schock\n• „Wenn etwas nicht stimmt“", "kw": "Aufnahme|aufnahme; Operation|operation; Mobilisation|mobilis; Hypertonie|hyper; Hypotonie|hypo; Kreislaufkollaps|kollaps; Medikamente|medikament; Schock|schock"}, {"id": "K010", "deck": "v", "q": "Grundsätze bei der Blutdruckmessung", "a": "• Stets unter gleichen Bedingungen messen, um verschiedene Werte beurteilen zu können: in Ruhe, immer im Liegen oder im Sitzen, immer am gleichen Arm.\n• Beim ersten Mal wird an beiden Armen gemessen.\n• Messung immer sofort dokumentieren.\n• Bei Abweichungen Arzt bzw. Pflegefachkraft informieren.", "kw": "gleichen Bedingungen|gleich; Ruhe; Liegen|lieg; Sitzen|sitz; gleichen Arm|arm; beiden Armen|beiden; dokumentieren|dokument; informieren|informier"}, {"id": "K011", "deck": "v", "q": "Warum wird beim ersten Mal an beiden Armen gemessen?", "a": "• Um den Ausgangswert festzustellen.\n• Beispiel: Bei einer Verengung der A. subclavia ist eine Druckdifferenz von mehr als 20 mmHg zwischen rechtem und linkem Arm möglich.", "kw": "Ausgangswert|ausgang; subclavia; Verengung|verengung; 20; Arm"}, {"id": "K012", "deck": "v", "q": "An welchem Arm darf der Blutdruck NICHT gemessen werden?", "a": "Nicht am jeweils betroffenen Arm messen:\n• bei Lymphödem (Arm geschwollen)\n• bei Parese / Plegie (Lähmung)\n• bei venösen oder arteriellen Gefäßzugängen (z. B. Viggo)\n• bei einem Dialyse-Shunt (auf keinen Fall!)\n• nach Ablatio mammae (Mastektomie)", "kw": "Lymphödem|lymph; Parese|parese; Plegie|plegie/lahmung; Gefäßzugänge|zugang; Viggo|viggo/wiggo; Shunt|shunt/schunt; Ablatio mammae|ablatio; Mastektomie|mastektomie"}, {"id": "K013", "deck": "v", "q": "Vorbereitung der auskultatorischen Blutdruckmessung", "a": "1. Pflegeempfänger hält ca. 15 Minuten Ruhephase ein – sonst falsch hohe Werte.\n2. Geeignete Manschette auswählen.\n3. Blutdruckmessgerät und Stethoskop bereitlegen.\n4. Lage: sitzen (Füße auf dem Boden) oder liegen.\n5. Kleidung, die den Arm bedeckt, entfernen – sie darf nicht einschnüren.\n6. Arm auf Herzhöhe abstützen, im Sitzen Ellenbogen leicht anwinkeln.", "kw": "Ruhephase|ruhe; Manschette|manschette; Stethoskop|stethoskop; Sitzen|sitz; Liegen|lieg; Kleidung|kleid; einschnüren|einschn; Herzhöhe|herz"}, {"id": "K014", "deck": "v", "q": "Manschette richtig anlegen", "a": "Luftleere Manschette am Oberarm ca. 2–3 cm oberhalb der Ellenbeuge anlegen. Die Markierung zeigt auf die Ellenbeuge (A. brachialis). Nicht zu locker und nicht zu fest: 1–2 Finger sollen gerade noch zwischen Arm und Manschette passen.", "kw": "luftleer|luftleer; Oberarm|oberarm; Ellenbeuge|ellenbeug; Markierung|markier; Finger; locker; fest"}, {"id": "K015", "deck": "v", "q": "Aufpumpen – bis wohin?", "a": "Ventil schließen. Aufblasballon pumpen, bis der Puls an der A. radialis nicht mehr tastbar ist. Dann noch weitere 30 mmHg aufpumpen und dabei den Manometerzeiger beobachten. Jetzt fließt unter dem aktuellen Druck kein Blut mehr durch die A. brachialis.", "kw": "Ventil; schließen|schliess; radialis; nicht mehr tastbar|tastbar; 30; Manometer; brachialis"}, {"id": "K016", "deck": "v", "q": "Abhören und Ablassen: wie geht das?", "a": "• Oliven des Stethoskops in die Ohren, Membran in die Ellenbeuge (A. brachialis) legen und mit Zeige- und Mittelfinger festhalten.\n• Ventil mit der anderen Hand langsam öffnen (3–5 mmHg pro Sekunde).\n• Erster hörbarer Ton: Manometerstand = systolischer Wert.\n• Letzter hörbarer Ton: Manometerstand = diastolischer Wert.\n• Restliche Luft zügig entweichen lassen.", "kw": "Oliven|oliv; Membran|membran; Ellenbeuge|ellenbeug; langsam|langsam; erster|erste; systolisch|systol; letzter|letzte; diastolisch|diastol"}, {"id": "K017", "deck": "v", "q": "Was sind Korotkow-Töne?", "a": "Pulssynchrone Strömungsgeräusche, die beim langsamen Ablassen der Luft über dem Stethoskop zu hören sind. Der erste Ton zeigt den systolischen, der letzte Ton den diastolischen Wert.", "kw": "pulssynchron|puls; Strömungsgeräusche|stromung; erster Ton|erste; systolisch|systol; letzter Ton|letzte; diastolisch|diastol"}, {"id": "K018", "deck": "v", "q": "Nachbereitung der Blutdruckmessung", "a": "1. Manschette entfernen.\n2. Pflegeempfänger über den gemessenen Wert informieren.\n3. Falls nötig, beim Ankleiden behilflich sein.\n4. Messgerät desinfizieren.\n5. Werte dokumentieren und die zuständige Pflegefachkraft informieren.", "kw": "Manschette|manschette; informieren|informier; Ankleiden|ankleid; desinfizieren|desinfi; dokumentieren|dokument; Pflegefachkraft|pflegefach"}, {"id": "K019", "deck": "v", "q": "Auskultatorisch oder oszillometrisch – was ist der Unterschied?", "a": "Auskultatorisch: manuell mit Manschette und Stethoskop; du hörst die Korotkow-Töne ab.\nOszillometrisch: elektronisch; das Gerät erfasst selbst die Druckschwankungen in der Manschette.", "kw": "auskultatorisch|auskult; Stethoskop|stethoskop; oszillometrisch|oszillo; elektronisch|elektron; Gerät|gerat"}, {"id": "K020", "deck": "w", "q": "Arteria (A.)", "a": "Schlagader – führt das Blut vom Herzen weg.", "kw": "Schlagader|schlag; Herz; Blut"}, {"id": "K021", "deck": "w", "q": "Vena (V.)", "a": "Vene, Blutader – führt das Blut zum Herzen zurück.", "kw": "Vene|vene; Blutader|blutader; Herz"}, {"id": "K022", "deck": "w", "q": "Kapillaren (lat. capillus = Haar)", "a": "Haargefäße – die kleinsten Blutgefäße zwischen Arterien und Venen.", "kw": "Haargefäße|haar; klein; Arterien|arteri; Venen|vene"}, {"id": "K023", "deck": "w", "q": "A. carotis", "a": "Halsschlagader – zentraler Pulsmessort.", "kw": "Hals; Schlagader|schlag"}, {"id": "K024", "deck": "w", "q": "A. femoralis", "a": "Leistenarterie – zentraler Pulsmessort.", "kw": "Leiste; Arterie|arteri"}, {"id": "K025", "deck": "w", "q": "A. temporalis", "a": "Schläfenarterie – peripherer Pulsmessort.", "kw": "Schläfe|schlaf; Arterie|arteri"}, {"id": "K026", "deck": "w", "q": "A. brachialis", "a": "Oberarmarterie – hier wird beim Blutdruckmessen abgehört.", "kw": "Oberarm|oberarm; Arterie|arteri"}, {"id": "K027", "deck": "w", "q": "A. radialis", "a": "Speichenarterie – am Handgelenk (Daumenseite), Standardort für die manuelle Pulsmessung.", "kw": "Speiche|speiche; Handgelenk|handgelenk; Daumen"}, {"id": "K028", "deck": "w", "q": "A. ulnaris", "a": "Ellenarterie – verläuft an der Elle (Kleinfingerseite des Unterarms).", "kw": "Elle|elle; Arterie|arteri"}, {"id": "K029", "deck": "w", "q": "A. poplitea", "a": "Kniekehlenarterie.", "kw": "Kniekehle|kniekehle"}, {"id": "K030", "deck": "w", "q": "A. tibialis posterior", "a": "Hintere Schienbeinarterie.", "kw": "hintere|hinter; Schienbein|schienbein"}, {"id": "K031", "deck": "w", "q": "A. dorsalis pedis", "a": "Fußrückenarterie (dorsal = Rücken, Pes/pedis = Fuß).", "kw": "Fußrücken|fussruck; Fuß|fuss; Rücken|ruck"}, {"id": "K032", "deck": "w", "q": "A. subclavia", "a": "Schlüsselbeinarterie (sub = unter, Clavicula = Schlüsselbein). Bei einer Verengung kann der Blutdruck zwischen den Armen um mehr als 20 mmHg abweichen.", "kw": "Schlüsselbein|schlussel; unter; Verengung|verengung; 20"}, {"id": "K033", "deck": "w", "q": "Hypertonie", "a": "Bluthochdruck (hyper = über, zu viel; Tonus = Spannung).", "kw": "Bluthochdruck|hoch; hyper|hyper; zu viel|viel"}, {"id": "K034", "deck": "w", "q": "Hypotonie", "a": "Zu niedriger Blutdruck (hypo = unter, zu wenig).", "kw": "niedrig; hypo|hypo; wenig"}, {"id": "K035", "deck": "w", "q": "Hyper- und Hypo-", "a": "Hyper- = über, zu viel. Hypo- = unter, zu wenig.", "kw": "über|uber; viel; unter; wenig"}, {"id": "K036", "deck": "w", "q": "Tachykardie und Bradykardie", "a": "Tachykardie = zu schneller Herzschlag (tachy = schnell).\nBradykardie = zu langsamer Herzschlag (brady = langsam).", "kw": "schnell; langsam; Herzschlag|herz"}, {"id": "K037", "deck": "w", "q": "-itis", "a": "Entzündung (z. B. Bronchitis = Entzündung der Bronchien).", "kw": "Entzündung|entzund"}, {"id": "K038", "deck": "w", "q": "kardiovaskulär", "a": "Herz (kardio) und Gefäße (vaskulär) betreffend – das Herz-Kreislauf-System.", "kw": "Herz; Gefäße|gefass"}, {"id": "K039", "deck": "w", "q": "Indikation", "a": "Grund bzw. Anlass, eine Maßnahme durchzuführen (z. B. Blutdruckmessung nach einem Unfall).", "kw": "Grund; Anlass; Maßnahme|massnahme"}, {"id": "K040", "deck": "w", "q": "Auskultation", "a": "Abhören (z. B. mit dem Stethoskop).", "kw": "Abhören|abhor; Stethoskop"}, {"id": "K041", "deck": "w", "q": "Stethoskop", "a": "Abhörgerät (griech. stethos = Brust, skopein = betrachten).", "kw": "Abhör|abhor; Gerät|gerat; Brust"}, {"id": "K042", "deck": "w", "q": "Manometer", "a": "Druckmessgerät – zeigt den Manschettendruck in mmHg an.", "kw": "Druck; mmHg|mmhg/millimeter; Messgerät|messgerat"}, {"id": "K043", "deck": "w", "q": "Parese", "a": "Unvollständige Lähmung (Teillähmung).", "kw": "unvollständig|unvollstand; Lähmung|lahmung; Teil"}, {"id": "K044", "deck": "w", "q": "Plegie", "a": "Vollständige Lähmung.", "kw": "vollständig|vollstand; Lähmung|lahmung"}, {"id": "K045", "deck": "w", "q": "Lymphödem", "a": "Schwellung durch gestaute Lymphflüssigkeit (Ödem = Wassereinlagerung im Gewebe). Am betroffenen Arm nicht den Blutdruck messen.", "kw": "Schwellung|schwell; Lymph; Wasser"}, {"id": "K046", "deck": "w", "q": "Ablatio mammae (Mastektomie)", "a": "Operative Entfernung der Brust. Am betroffenen Arm nicht den Blutdruck messen.", "kw": "Entfernung|entfern; Brust; Operation|operat"}, {"id": "K047", "deck": "w", "q": "Dialyse-Shunt", "a": "Operativ angelegte Verbindung zwischen Arterie und Vene am Arm für die Dialyse. Dort auf keinen Fall Blutdruck messen!", "kw": "Verbindung|verbind; Arterie|arteri; Vene|vene; Dialyse|dialyse; keinen Fall|kein"}, {"id": "K048", "deck": "w", "q": "Viggo", "a": "Handelsname für eine venöse Verweilkanüle (Venenzugang). Am Arm mit Gefäßzugang nicht den Blutdruck messen.", "kw": "Venenzugang|venen/zugang; Kanüle|kanul; Vene|vene"}, {"id": "K049", "deck": "w", "q": "Mobilisation", "a": "Den Pflegeempfänger in Bewegung bringen, z. B. Aufstehen aus dem Bett. Vorher werden oft Puls und Blutdruck kontrolliert.", "kw": "Bewegung|beweg; Aufstehen|aufsteh; Bett"}, {"id": "K050", "deck": "w", "q": "Prophylaxe", "a": "Vorbeugung (z. B. Dekubitusprophylaxe, Sturzprophylaxe).", "kw": "Vorbeugung|vorbeug; Dekubitus|dekubitus; Sturz"}, {"id": "K051", "deck": "w", "q": "Dekubitus", "a": "Druckgeschwür (Wundliegen). Dazu gibt es einen Expertenstandard: Dekubitusprophylaxe.", "kw": "Druck; Geschwür|geschwur; Wundliegen|wundlieg"}, {"id": "K052", "deck": "w", "q": "kurativ", "a": "Heilend – Wiederherstellung der Gesundheit ist möglich (Krankenhaus, ambulante Pflege).", "kw": "heilend|heil; Gesundheit|gesundheit; Krankenhaus|krankenhaus"}, {"id": "K053", "deck": "w", "q": "präventiv", "a": "Vorbeugend, verhütend (Prävention) – Maßnahmen, damit unerwünschte Ereignisse gar nicht erst entstehen.", "kw": "vorbeugend|vorbeug; verhüt|verhut; Prävention|praventi"}, {"id": "K054", "deck": "w", "q": "rehabilitativ", "a": "Wiederherstellend – Wiedereingliederung nach Krankheit (medizinisch, beruflich, sozial), z. B. in Reha-Kliniken.", "kw": "Wiederherstellung|wiederherstell; Wiedereingliederung|wiedereingl; Reha"}, {"id": "K055", "deck": "w", "q": "palliativ", "a": "Lindernd – Beschwerden und Schmerzen lindern, um die Lebensqualität zu verbessern (Hospiz, Palliativstation).", "kw": "lindernd|linder; Schmerz; Lebensqualität|lebensqualitat; Hospiz"}, {"id": "K056", "deck": "w", "q": "Salutogenese", "a": "lat. salus = Gesundheit, Wohlbefinden; griech. Genese = Entstehung. Rahmenkonzept zur Entstehung und Erhaltung von Gesundheit.", "kw": "Gesundheit|gesundheit; Entstehung|entstehung; Erhaltung|erhalt"}, {"id": "K057", "deck": "w", "q": "Pathogenese", "a": "griech. patho = Leiden; Genese = Entstehung. Krankheitsentstehung – Modell zur Analyse und Kontrolle von Risikofaktoren.", "kw": "Leiden|leid; Krankheit|krankheit; Entstehung|entstehung; Risikofaktoren|risiko"}, {"id": "K058", "deck": "w", "q": "Resilienz", "a": "Psychische Widerstandskraft – Krisen bewältigen. Resilienzfaktoren stärken, statt nur Defizite zu sehen.", "kw": "Widerstandskraft|widerstand; Krise|kris"}, {"id": "K059", "deck": "w", "q": "evidenzbasiert", "a": "Auf wissenschaftlichen Belegen (Evidenz) beruhend – so sind z. B. die Expertenstandards entwickelt.", "kw": "wissenschaft; Belege|beleg; Evidenz|eviden"}, {"id": "K060", "deck": "w", "q": "intrinsisch und extrinsisch", "a": "Intrinsisch = von innen heraus (Freude an der Sache). Extrinsisch = von außen (Belohnung, Lob, Noten, Geld).", "kw": "innen; außen|aussen; Belohnung|belohn"}, {"id": "K061", "deck": "w", "q": "deklaratives und nondeklaratives Gedächtnis", "a": "Deklarativ = Fachwissen, das man benennen kann. Nondeklarativ = Erfahrungen, Gewohnheiten, Bewegungsabläufe. Beides ist im Langzeitgedächtnis gespeichert.", "kw": "Fachwissen|fachwissen; Erfahrung|erfahrung; Gewohnheit|gewohn; Bewegungsabläufe|bewegung; Langzeit"}, {"id": "K062", "deck": "w", "q": "Vitalzeichen", "a": "Lebenszeichen, z. B. Blutdruck, Puls, Atmung, Temperatur.", "kw": "Blutdruck|blutdruck; Puls; Atmung|atmung; Temperatur|temperatur"}, {"id": "K063", "deck": "s", "q": "Wie wird Pflege definiert? (ICN)", "a": "Pflege umfasst die eigenverantwortliche Versorgung und Betreuung von Menschen aller Altersgruppen, von Familien und Gemeinschaften, ob krank oder gesund, in allen Lebenssituationen – allein oder zusammen mit anderen Berufsgruppen.\nDazu gehören Förderung der Gesundheit, Verhütung von Krankheiten sowie Versorgung und Betreuung kranker, behinderter und sterbender Menschen.", "kw": "eigenverantwortlich|eigenverantwort; Versorgung|versorg; Betreuung|betreu; Altersgruppen|alter; Gesundheit|gesundheit; Verhütung|verhut; sterbende|sterben"}, {"id": "K064", "deck": "s", "q": "Welche Aufgaben übernimmt man in der Pflege?", "a": "Beratung von kranken und pflegebedürftigen Menschen mit körperlichen oder psychischen Einschränkungen sowie Betreuung, Versorgung und Aktivierung zum Erhalt von Fähigkeiten und Fertigkeiten im Alltag, z. B. Grundpflege.", "kw": "Beratung|beratung; Betreuung|betreu; Versorgung|versorg; Aktivierung|aktivier; Grundpflege|grundpflege"}, {"id": "K065", "deck": "s", "q": "Wie hat sich die Pflege geschichtlich entwickelt?", "a": "Über mehrere Jahrhunderte von der Pflege aus Nächstenliebe und Barmherzigkeit zu einem anerkannten Berufsbild. Vor allem im 20. Jahrhundert gab es viele berufspolitische Entwicklungen, die ersten Berufsbilder wurden begründet und die Ausbildung mehrfach reformiert. Das Pflegeberufereformgesetz (seit 2020 gültig) macht einen weiteren Schritt Richtung Profession.", "kw": "Nächstenliebe|nachstenliebe; Barmherzigkeit|barmherz; Berufsbild|berufsbild; 20; Reform|reform; Profession|profession"}, {"id": "K066", "deck": "s", "q": "Was gehört zu den Aufgaben von Pflegefachassistentinnen und -assistenten?", "a": "• Unterstützung, Übernahme und Anleitung bei Körperhygiene, Mobilisation, prophylaktischen Maßnahmen, Ausscheidung und Ernährung\n• Unterstützung und Begleitung bei anfallenden Aufgaben außerhalb der Wohnung\n• Mitwirkung bei diagnostischen und therapeutischen Maßnahmen\n• Dokumentation, Protokolle und Arbeitsnachweise", "kw": "Körperhygiene|hygiene; Mobilisation|mobilis; prophylaktisch|prophylakt; Ausscheidung|ausscheid; Ernährung|ernahr; Mitwirkung|mitwirk; Dokumentation|dokument"}, {"id": "K067", "deck": "s", "q": "Wie ist die Ausbildung zur Pflegefachassistenz aufgebaut?", "a": "Einjährige Ausbildung mit theoretischem und praktischem Unterricht (laut Skript 700 Stunden) sowie praktischer Ausbildung. Sie schließt mit einer staatlich anerkannten Prüfung nach Landesrecht ab. (Bitte die Zahlen im Skript noch einmal gegenprüfen.)", "kw": "einjährig|einjahr; Unterricht|unterricht; praktisch|prakti; staatlich|staatlich; Prüfung|prufung"}, {"id": "K068", "deck": "s", "q": "Was ist Laienpflege?", "a": "Pflegende Tätigkeiten, die eine Person übernimmt, die keine Ausbildung im Pflegebereich hat. Oft sind es Angehörige oder Bekannte der pflegebedürftigen Person.", "kw": "Ausbildung|ausbildung; Angehörige|angehor; Bekannte|bekannt; keine"}, {"id": "K069", "deck": "s", "q": "Was beschreiben Expertenstandards?", "a": "Evidenzbasierte Qualitätsinstrumente, die von Pflegeexperten erarbeitet wurden und auf dem Konsens der Berufsgruppe beruhen. Sie sollen die Qualität in der Pflege spürbar verbessern. Entwickelt vom DNQP (Deutsches Netzwerk für Qualitätsentwicklung in der Pflege; im Skript steht „Qualitätssicherung“) mit dem Deutschen Pflegerat und mit Förderung des Bundesgesundheitsministeriums.", "kw": "Qualität|qualitat; evidenzbasiert|evidenz; Konsens|konsens; DNQP|dnqp/netzwerk; Pflegerat|pflegerat"}, {"id": "K070", "deck": "s", "q": "Nenne Beispiele für Expertenstandards", "a": "• Dekubitusprophylaxe in der Pflege\n• Schmerzmanagement in der Pflege\n• Sturzprophylaxe in der Pflege\n• Beziehungsgestaltung in der Pflege von Menschen mit Demenz\n• Förderung der Mundgesundheit in der Pflege", "kw": "Dekubitus|dekubitus; Schmerz|schmerz; Sturz|sturz; Demenz|demenz; Mundgesundheit|mundgesund"}, {"id": "K071", "deck": "s", "q": "Wozu sind Pflegefachassistentinnen und -assistenten verpflichtet?", "a": "Sie sind verpflichtet, die wissenschaftlichen und gesetzlichen Grundlagen der pflegebedürftigen Menschen zu sehen, zu respektieren und zu beachten.", "kw": "wissenschaftlich|wissenschaft; gesetzlich|gesetz; sehen; respektieren|respekt; beachten|beacht"}, {"id": "K072", "deck": "s", "q": "Grundgesetz Artikel 1", "a": "„Die Würde des Menschen ist unantastbar.“ Dieser Satz bildet die Basis für ein friedliches Zusammenleben und für ein würdevolles, personenzentriertes Pflegeverständnis.", "kw": "Würde|wurde; Menschen|mensch; unantastbar|unantast"}, {"id": "K073", "deck": "s", "q": "Wofür gibt es die Pflege-Charta?", "a": "Die Pflege-Charta wurde von Vertretern aus allen Bereichen der Pflege und Selbsthilfe entwickelt, um die Rechte der Betroffenen zu stärken und eine Grundlage für eine würdevolle Pflegepraxis zu schaffen. Sie umfasst acht Artikel.", "kw": "Rechte|recht; Betroffenen|betroffen; würdevoll|wurdevoll; Pflegepraxis|pflegepraxis; acht|acht/8"}, {"id": "K074", "deck": "s", "q": "Pflege-Charta Artikel 1", "a": "Selbstbestimmung und Hilfe zur Selbsthilfe – das Recht auf ein möglichst selbstbestimmtes Leben und auf Unterstützung zur Selbsthilfe.", "kw": "Selbstbestimmung|selbstbestimm; Selbsthilfe|selbsthilfe; Unterstützung|unterstutz"}, {"id": "K075", "deck": "s", "q": "Pflege-Charta Artikel 2", "a": "Körperliche und seelische Unversehrtheit, Freiheit und Sicherheit – das Recht, vor Gefahren für Leib und Seele geschützt zu werden und in Freiheit und Sicherheit zu leben.", "kw": "körperlich|korper; seelisch|seel; Unversehrtheit|unversehrt; Freiheit|freiheit; Sicherheit|sicherheit"}, {"id": "K076", "deck": "s", "q": "Pflege-Charta Artikel 3", "a": "Privatheit – das Recht auf Wahrung und Schutz der Privat- und Intimsphäre.", "kw": "Privat|privat; Intimsphäre|intim; Schutz|schutz"}, {"id": "K077", "deck": "s", "q": "Pflege-Charta Artikel 4", "a": "Pflege, Betreuung und Behandlung – das Recht auf eine qualifizierte, auf den persönlichen Bedarf ausgerichtete Pflege und Behandlung.", "kw": "qualifiziert|qualifiz; persönlich|personlich; Bedarf|bedarf; Behandlung|behandlung"}, {"id": "K078", "deck": "s", "q": "Pflege-Charta Artikel 5", "a": "Information, Beratung und Aufklärung – das Recht auf umfassende Informations-, Hilfe- und Behandlungsangebote.", "kw": "Information|information; Beratung|beratung; Aufklärung|aufklar; umfassend|umfassend"}, {"id": "K079", "deck": "s", "q": "Pflege-Charta Artikel 6", "a": "Kommunikation, Wertschätzung und Teilhabe – das Recht auf Wertschätzung und Austausch mit anderen Menschen, um am gesellschaftlichen Leben teilzunehmen.", "kw": "Kommunikation|kommunikation; Wertschätzung|wertschatz; Teilhabe|teilhabe; Austausch|austausch"}, {"id": "K080", "deck": "s", "q": "Pflege-Charta Artikel 7", "a": "Religion, Kultur und Weltanschauung – das Recht, entsprechend der eigenen Kultur und Weltanschauung zu leben und die Religion auszuüben.", "kw": "Religion|religion; Kultur|kultur; Weltanschauung|weltanschau"}, {"id": "K081", "deck": "s", "q": "Pflege-Charta Artikel 8", "a": "Palliative Begleitung, Sterben und Tod – das Recht, in Würde zu sterben und eine entsprechende palliative Begleitung zu erhalten.", "kw": "palliativ|palliativ; Begleitung|begleit; Sterben|sterb; Würde|wurde"}, {"id": "K082", "deck": "s", "q": "Für wen gilt der ICN-Ethikkodex?", "a": "Er gilt in allen Mitgliedsstaaten des ICN (International Council of Nurses) und richtet sich an Pflegefachpersonen aller Qualifikationsstufen – egal, in welchen Arbeitsfeldern oder Praxisgebieten sie tätig sind, z. B. in Pflegeheimen, Krankenhäusern und der ambulanten Pflege.", "kw": "Mitgliedsstaaten|mitglied; ICN|icn; Qualifikation|qualifikation; Arbeitsfeld|arbeitsfeld; ambulant|ambulant"}, {"id": "K083", "deck": "s", "q": "Wie viele Grundelemente hat der ICN-Ethikkodex?", "a": "Vier:\n1. Pflegende und ihre Mitmenschen\n2. Pflegende und die Pflegepraxis\n3. Pflegende und ihre Profession\n4. Pflegende und ihre Kollegen (so im Skript; die neuere ICN-Fassung von 2021 nennt hier „Pflegefachpersonen und globale Gesundheit“ – bei der Lehrkraft nachfragen)", "kw": "vier|vier/4; Mitmenschen|mitmensch; Pflegepraxis|pflegepraxis; Profession|profession; Kollegen|kolleg"}, {"id": "K084", "deck": "s", "q": "ICN-Kodex Element 1: Pflegende und ihre Mitmenschen", "a": "Pflegende respektieren die Würde, das Leben, die Gesundheit, die Freiheit, die Meinungen, die Sitten, Gewohnheiten und Bedürfnisse aller Menschen – unabhängig von Alter, Geschlecht, Hautfarbe, Religion, sozialem Status oder anderen Merkmalen.", "kw": "Würde|wurde; Leben|leben; Gesundheit|gesundheit; Freiheit|freiheit; unabhängig|unabhang; Alter|alter; Religion|religion"}, {"id": "K085", "deck": "s", "q": "ICN-Kodex Element 2: Pflegende und die Pflegepraxis", "a": "Pflegende sind persönlich verantwortlich für ihre berufliche Tätigkeit. Sie müssen fachlich kompetent bleiben, z. B. durch Weiterbildung, und gewährleisten Sicherheit und Würde der Patienten bei der Anwendung neuer Technologien und wissenschaftlicher Erkenntnisse.", "kw": "verantwortlich|verantwort; kompetent|kompetent; Weiterbildung|weiterbild; Sicherheit|sicherheit; Würde|wurde; Technologien|technolog"}, {"id": "K086", "deck": "s", "q": "ICN-Kodex Element 3: Pflegende und ihre Profession", "a": "Pflegende haben die Verantwortung, die Integrität und die Qualität der Pflege professionell zu wahren. Dazu gehören die Mitwirkung an Forschung, das Setzen von Standards und die Einhaltung der Berufsregeln.", "kw": "Verantwortung|verantwort; Integrität|integrit; Qualität|qualit; Forschung|forschung; Standards|standard; Berufsregeln|berufsregeln"}, {"id": "K087", "deck": "s", "q": "Die Maslow-Bedürfnispyramide (von unten nach oben)", "a": "1. Physiologische Bedürfnisse – Atmen, Essen, Trinken, Schlaf, Wärme\n2. Sicherheitsbedürfnisse – Schutz, Stabilität, Ordnung\n3. Soziale Bedürfnisse – Zugehörigkeit, Kommunikation, Freundschaft, Liebe\n4. Individualbedürfnisse – Anerkennung, Wertschätzung, Status\n5. Selbstverwirklichung – die eigenen Fähigkeiten entfalten", "kw": "physiologisch|physiolog; Sicherheit|sicherheit; sozial|sozial; Individual|individual; Anerkennung|anerkenn; Selbstverwirklichung|selbstverwirk"}, {"id": "K088", "deck": "s", "q": "Welche vier Handlungsfelder der Pflege gibt es?", "a": "• kurativ – heilend (Krankenhaus, ambulante Pflege)\n• präventiv – vorbeugend (private Räume, ambulante Versorgung)\n• rehabilitativ – Wiederherstellung (Reha-Kliniken)\n• palliativ – lindernd (Hospiz, Palliativstation)", "kw": "kurativ|kurativ; präventiv|praventiv; rehabilitativ|rehabilit; palliativ|palliativ; Krankenhaus|krankenhaus; Hospiz|hospiz"}, {"id": "K089", "deck": "s", "q": "Was bedeutet Handeln?", "a": "Aufgabengemäß, zielgerichtet und verantwortungsbewusst tätig werden, situationsbedingt aktiv werden und Probleme lösen. Alltägliches Handeln wird durch Übung automatisiert; so entstehen feste, kraftsparende Gewohnheiten, die weitgehend unbewusst ablaufen und das Denken für andere Prozesse entlasten.", "kw": "aufgabengemäß|aufgabengema; zielgerichtet|zielgericht; verantwortungsbewusst|verantwortungsbewusst; situationsbedingt|situation; Probleme|problem; Gewohnheit|gewohn"}, {"id": "K090", "deck": "s", "q": "Was bedeutet Kompetenz?", "a": "Die Fähigkeit und Bereitschaft des Einzelnen, Kenntnisse und Fertigkeiten sowie persönliche, soziale und methodische Fähigkeiten zu nutzen und sich durchdacht, individuell und sozialverantwortlich zu verhalten. Man spricht von Handlungskompetenz.", "kw": "Fähigkeit|fahigkeit; Bereitschaft|bereitschaft; Kenntnisse|kenntnis; Fertigkeiten|fertigkeit; sozialverantwortlich|sozialverantwort; Handlungskompetenz|handlungskompetenz"}, {"id": "K091", "deck": "s", "q": "Fachkompetenz – was gehört dazu?", "a": "Fachlich-inhaltliches Lernen: berufliche Grundlagen kennen, anwenden und beurteilen. Sie umfasst theoretische Kenntnisse und praktisch anwendbares Handlungswissen.\nBeispiel: wissenschaftliche Erkenntnisse einbeziehen, Zusammenhänge verstehen, Expertenstandards und RKI-Richtlinien in der beruflichen Praxis anwenden.", "kw": "Kenntnisse|kenntnis; Fertigkeiten|fertigkeit; Anwenden|anwend; Expertenstandards|expertenstandard; RKI|rki"}, {"id": "K092", "deck": "s", "q": "Methodenkompetenz – was gehört dazu?", "a": "Planmäßig und zielorientiert vorgehen, nichts dem Zufall überlassen: problemlösendes Denken, Analyse-, Transfer-, Planungs- und Entscheidungsfähigkeit, Informationsbeschaffung, Rhetorik.\nBeispiel: Pflegehandlungen zielorientiert durchführen, sich selbst organisieren, Prioritäten setzen.", "kw": "planmäßig|planmass; zielorientiert|zielorient; Problem|problem; Planung|planung; Entscheidung|entscheid; Prioritäten|prioritat; organisieren|organis"}, {"id": "K093", "deck": "s", "q": "Sozialkompetenz – was gehört dazu?", "a": "Beziehungen gestalten und mit anderen Menschen situationsadäquat handeln: Teamfähigkeit, Hilfsbereitschaft, Fairness, Kooperation, Konfliktfähigkeit, Toleranz, Kritik annehmen und äußern.\nBeispiel: Pflegeprozesse als Beziehungsprozess gestalten, Biographiearbeit, Umgang mit herausforderndem Verhalten.", "kw": "Team; Hilfsbereitschaft|hilfsbereit; Kooperation|kooperation; Konflikt|konflikt; Toleranz|toleranz; Biographiearbeit|biographie"}, {"id": "K094", "deck": "s", "q": "Persönlichkeitskompetenz – was gehört dazu?", "a": "Die eigene Persönlichkeit weiterentwickeln, Einstellungen und Werte reflektieren: Verantwortlichkeit, Kreativität, Motivation, Initiative, Lernbereitschaft, Ausdauer, emotionale Intelligenz, realistisches Selbstbild.\nBeispiel: das eigene Handeln kontinuierlich reflektieren, sich selbst realistisch einschätzen, konstruktive Kritik vertragen.", "kw": "Verantwortung|verantwort; Kreativität|kreativ; Motivation|motivation; Initiative|initiativ; emotionale Intelligenz|emotional; Selbstbild|selbstbild; Reflexion|reflek"}, {"id": "K095", "deck": "l", "q": "Was ist Lernen? (Definition)", "a": "Lernen ist die lebenslange Aneignung von Wissen, Kenntnissen und Fertigkeiten. Es ist ein Prozess, baut auf Erfahrungen auf und führt zu Veränderungen im Verhalten und Erleben (Hobmair 2013).", "kw": "lebenslang|lebenslang; Aneignung|aneignung; Wissen|wissen; Fertigkeiten|fertigkeit; Prozess|prozess; Erfahrung|erfahrung"}, {"id": "K096", "deck": "l", "q": "Welche drei Gedächtnisstufen gibt es?", "a": "• Ultrakurzzeitgedächtnis: Millisekunden, wirkt wie ein Filter\n• Kurzzeitgedächtnis: Sekunden bis wenige Minuten, höchstens 9 Stück neue Informationen (Lesen: Zwischenspeicher ca. 20 Minuten)\n• Langzeitgedächtnis: Tage bis Jahre", "kw": "Ultrakurzzeit|ultrakurz; Kurzzeit|kurzzeit; Langzeit|langzeit; Filter|filter; 9|9/neun; 20|20/zwanzig"}, {"id": "K097", "deck": "l", "q": "Ultrakurzzeitgedächtnis – wie funktioniert es?", "a": "Es speichert nur Millisekunden und agiert wie ein Filter: Es lässt maximal zwei Sekunden lang alle einkommenden Sinnesreize durch und sortiert Wichtiges von Unwichtigem. Nur Wichtiges kommt ins Kurzzeitgedächtnis.", "kw": "Millisekunden|millisekunde; Filter|filter; Sinnesreize|sinnes; wichtig|wichtig"}, {"id": "K098", "deck": "l", "q": "Kurzzeitgedächtnis – wie funktioniert es?", "a": "Es ist der Arbeitsspeicher: Speicherdauer Sekunden bis höchstens wenige Minuten, nur etwa 9 Informationen gleichzeitig. Ohne Wiederholung und Aufmerksamkeit geht der Inhalt schnell wieder verloren. Es dient als Zwischenstation zum Langzeitgedächtnis.", "kw": "Arbeitsspeicher|arbeitsspeicher; Sekunden|sekunde; Minuten|minute; 9|9/neun; Wiederholung|wiederhol; Aufmerksamkeit|aufmerksam"}, {"id": "K099", "deck": "l", "q": "Langzeitgedächtnis – was wird dort gespeichert?", "a": "Speicherdauer: Tage bis Jahre. Gespeichert werden deklaratives Wissen (Fachwissen) und nondeklaratives Wissen (Erfahrungen, Gewohnheiten, Bewegungsabläufe).", "kw": "Tage; Jahre; deklarativ|deklarativ; Fachwissen|fachwissen; Erfahrung|erfahrung; Gewohnheiten|gewohn; Bewegungsabläufe|bewegung"}, {"id": "K100", "deck": "l", "q": "Was passiert im Gehirn, wenn du etwas Neues lernst?", "a": "Nervenzellen empfangen und senden Informationen über Synapsen (Kontaktstellen). Wenn du etwas wiederholt tust, werden die Nervenbahnen dicker und es bilden sich neue Verbindungen. Wie eine Karte, die erst unscharf ist und mit jeder Wiederholung schärfer und detailreicher wird. Darum ist Wiederholung so wichtig.", "kw": "Nervenzellen|nerven; Synapsen|synaps; Kontaktstellen|kontakt; Wiederholung|wiederhol; dicker|dick; Verbindungen|verbind"}, {"id": "K101", "deck": "l", "q": "Was bedeutet lebenslanges Lernen?", "a": "Lernen während der gesamten Lebensphase, privat und beruflich (Fort- und Weiterbildung im Beruf). Mit Globalisierung und technologischem Fortschritt muss jeder Erwachsene neue Fähigkeiten aneignen. Eine Lernmentalität zu entwickeln wird immer wichtiger.", "kw": "gesamte|gesamt; Lebensphase|lebensphase; Fort|fort; Weiterbildung|weiterbild; Globalisierung|globalis; Lernmentalität|lernmental"}, {"id": "K102", "deck": "l", "q": "Wie lernt man als Kind, als Schulkind und als Erwachsener?", "a": "• Kind: „Ich lerne, weil es mir Spaß macht.“ Neugierig, frei, aus Interesse.\n• Schulkind: „Ich lerne, weil ich das muss.“ Noten, Lehrpläne, Fremdbestimmung.\n• Erwachsener: „Ich lerne, weil ich es lernen will.“ Freiwillig, selbstbestimmt, mit Relevanz und Praxisbezug.", "kw": "Kind; Spaß|spass; Schulkind|schul; muss; Erwachsene|erwachsen; will; freiwillig|freiwillig"}, {"id": "K103", "deck": "l", "q": "Was zeichnet das Lernen von Erwachsenen aus?", "a": "Erwachsene lernen freiwillig, gemeinschaftlich und selbstbestimmt, bringen Vorerfahrungen mit und werden durch Relevanz und Praxisbezug motiviert. Sie handeln problemorientiert und brauchen Freiraum, damit individuelle Lernpräferenzen berücksichtigt werden.", "kw": "freiwillig|freiwillig; gemeinschaftlich|gemeinschaft; selbstbestimmt|selbstbestimm; Praxisbezug|praxisbezug; Relevanz|relevanz; problemorientiert|problemorient; Freiraum|freiraum"}, {"id": "K104", "deck": "l", "q": "Was sind formales, non-formales und informelles Lernen?", "a": "Formales Lernen: organisiert, strukturiert, rein auf das Lernen fokussiert und führt zu einer Qualifikation oder einem Zertifikat.\nInformelles Lernen: findet im (Berufs-)Alltag statt, unbewusst und nicht zertifizierbar.\nNon-formales Lernen liegt dazwischen.", "kw": "formal|formal; organisiert|organis; strukturiert|struktur; Zertifikat|zertifikat; informell|informell; Alltag|alltag; unbewusst|unbewusst"}, {"id": "K105", "deck": "l", "q": "Die drei Phasen der Prüfungsvorbereitung", "a": "1. Vorbereitungsphase: alle Materialien sammeln, Wissensstand analysieren, Zeitplan erstellen.\n2. Informationsaufbauphase: Lernstoff nach Wichtigkeit ordnen und mit Lerntechniken wie Mindmapping erstmals durcharbeiten.\n3. Aneignungsphase: wiederholen, nachlesen, vertiefen und festigen, Probeprüfungen in der Lerngruppe.", "kw": "Vorbereitung|vorbereit; Informationsaufbau|informationsaufbau; Aneignung|aneignung; Mindmap|mindmap; wiederholen|wiederhol; Zeitplan|zeitplan; Lerngruppe|lerngruppe"}, {"id": "K106", "deck": "l", "q": "Welche Tipps helfen, sich zum Lernen zu motivieren?", "a": "• Rituale entwickeln (z. B. eine Tasse Tee vor dem Start)\n• Lernpartner suchen\n• Positive Einstellung entwickeln\n• Lernplatz wechseln\n• Sich nach Lernphasen belohnen\n• Visualisieren: sich erinnern, warum man das Fach gewählt hat\n• Angenehme Lernumgebung ohne Ablenkung", "kw": "Rituale|ritual; Lernpartner|lernpartner; positive Einstellung|positiv; Lernplatz|lernplatz/ort; belohnen|belohn; Visualisieren|visualis; Lernumgebung|lernumgebung"}, {"id": "K107", "deck": "l", "q": "Wie sieht eine gute Lernumgebung aus?", "a": "Ablenkungsfrei: aufgeräumter Arbeitsplatz, ausreichend Platz, Helligkeit und Ruhe, ein gemütlicher Stuhl, alle Lernmaterialien bereit. Pausen einplanen und aktiv gestalten. Unterricht aktiv als Lernchance nutzen.", "kw": "ablenkungsfrei|ablenk; aufgeräumt|aufgeraum; Licht|licht/hell; Ruhe|ruhe; Pausen|pause; Lernmaterial|lernmaterial"}, {"id": "K108", "deck": "l", "q": "Welche zwei Hauptarten der Motivation gibt es?", "a": "Intrinsische Motivation (kommt von innen, z. B. Freude an einer Tätigkeit) und extrinsische Motivation (kommt von außen, z. B. Belohnungen oder Druck). Beide wirken unterschiedlich auf Verhalten und Leistung.", "kw": "intrinsisch|intrinsi; extrinsisch|extrinsi; innen; außen|aussen; Belohnung|belohn"}, {"id": "K109", "deck": "l", "q": "Intrinsische Motivation – Definition, Merkmal, Beispiel", "a": "Definition: Der Antrieb, eine Tätigkeit aus eigenem Interesse, für den Spaß an der Sache oder aus innerer Überzeugung auszuführen.\nMerkmal: kommt von innen, ist schwerer zu stimulieren, hat aber eine länger anhaltende Wirkung und führt oft zu höherer Kreativität und Ausdauer.\nBeispiel: ein Hobby, das man aus reiner Freude ausübt.", "kw": "Antrieb|antrieb; Interesse|interesse; Spaß|spass; Überzeugung|uberzeug; innen; Hobby|hobby; Ausdauer|ausdauer"}, {"id": "K110", "deck": "l", "q": "Extrinsische Motivation – Definition, Merkmal, Beispiel", "a": "Definition: Der Antrieb, eine Handlung auszuführen, um äußere Anreize zu erhalten oder negative Konsequenzen zu vermeiden.\nMerkmal: kommt von externen Quellen; die Belohnung ist ein direkter „Booster“, wirkt aber begrenzter und kurzfristiger.\nBeispiel: arbeiten für eine Gehaltserhöhung, Lob oder Anerkennung.", "kw": "Anreize|anreiz; Konsequenzen|konsequenz; extern|extern; Belohnung|belohn; kurzfristig|kurzfrist; Gehaltserhöhung|gehalt; Lob|lob"}, {"id": "K111", "deck": "l", "q": "Was fördert die intrinsische Motivation beim Lernen?", "a": "Positive Einstellung, Neugier und Offenheit gegenüber dem Lernthema; Lernziele formulieren und zeitlich festlegen (Planung); Selbstvertrauen zur eigenen Leistung stärken; Unterstützungsangebote nutzen. Dazu gehören Autonomie, Kompetenzerleben, Sinnhaftigkeit und soziale Eingebundenheit.", "kw": "Neugier|neugier; Offenheit|offen; Lernziele|lernziel; Selbstvertrauen|selbstvertrau; Unterstützung|unterstutz; Autonomie|autonomie"}, {"id": "K112", "deck": "l", "q": "Was fördert die extrinsische Motivation beim Lernen?", "a": "Äußere Anreize und Einflüsse: Lob und Anerkennung, gute Noten, finanzielle Anreize wie Bezahlung oder Gehaltserhöhung, eine angenehme Lernumgebung, zusätzliche Verantwortung. Sie wirken oft nur kurzfristig und sollen die intrinsische Motivation nicht unterdrücken. Lernerfolge feiern und belohnen.", "kw": "Lob|lob; Anerkennung|anerkenn; Noten|note; Gehaltserhöhung|gehalt; Lernumgebung|lernumgebung; kurzfristig|kurzfrist; belohnen|belohn"}, {"id": "K113", "deck": "l", "q": "Welche vier Lerntypen gibt es?", "a": "• Visueller Typ: lernt durch Ansehen (Videos, Grafiken, Mindmaps)\n• Auditiver Typ: lernt durch lautes Vorlesen und Anhören\n• Kommunikativer Typ: lernt durch Gespräche, in Lerngruppen\n• Motorischer Typ: lernt durch Ausprobieren und Anwenden („Learning by doing“)", "kw": "visuell|visuell; auditiv|auditiv; kommunikativ|kommunikativ; motorisch|motorisch; Ansehen|ansehen; Anhören|anhor; Gespräche|gesprach; Ausprobieren|ausprobier"}, {"id": "K114", "deck": "l", "q": "Lerntipps für den visuellen Typ", "a": "Möglichst viel mitschreiben, Skizzen, Mind-Maps und Diagramme malen, Stoff in Bilder fassen, Karteikarten nutzen, Bilder und Internetbilder zum Thema suchen und Zusammenhänge verbildlichen (z. B. Eselsbrücken mit Bildern).", "kw": "mitschreiben|mitschreib; Skizzen|skizz; Mindmap|mind; Diagramme|diagramm; Karteikarten|karteikart; Bilder|bild"}, {"id": "K115", "deck": "l", "q": "Lerntipps für den auditiven Typ", "a": "Texte laut vorlesen, Lernstoff aufnehmen und anhören, Lern-CDs, Hörbücher und Podcasts nutzen, Selbstgespräche führen, jemandem etwas erklären. Ruhige Umgebung, damit Geräusche nicht ablenken.", "kw": "laut; vorlesen|vorles; aufnehmen|aufnehm; Podcast|podcast; Hörbücher|horbuch; erklären|erklar"}, {"id": "K116", "deck": "l", "q": "Lerntipps für den kommunikativen Typ", "a": "Mit Freunden oder Lernpartnern lernen, den Stoff besprechen und diskutieren, Rollenspiele machen, Quizrunden spielen, dem Lernpartner das Thema erklären.", "kw": "Lernpartner|lernpartner/freunde; besprechen|besprech; diskutieren|diskut; Rollenspiele|rollenspiel; Quiz|quiz; erklären|erklar"}, {"id": "K117", "deck": "l", "q": "Lerntipps für den motorischen Typ", "a": "Mit Händen lernen: Modelle basteln, Lernmaterial anfassen, Rollenspiele spielen, beim Lernen im Zimmer auf und ab laufen, Gesten und Mimik einsetzen, einen Ball oder Stift in der Hand haben.", "kw": "Modelle|modell; basteln|bastel; Rollenspiele|rollenspiel; laufen|lauf; Gesten|geste; Ball|ball"}, {"id": "K118", "deck": "l", "q": "Weiterbildung oder Fortbildung – was ist der Unterschied?", "a": "Weiterbildung: man eignet sich neue Fähigkeiten, Kenntnisse und Qualifikationen an, nach dem Berufsabschluss, mittlere bis längere Dauer, oft mit Aufstieg verbunden (z. B. Praxisanleiter, Fachkrankenpflege).\nFortbildung: erweitert oder ergänzt die Qualifikationen im aktuellen Beruf, kürzere Dauer, Aktualisierung von Wissen (z. B. Kommunikation, EDV, Pflegedokumentation).", "kw": "Weiterbildung|weiterbildung; neue Qualifikation|neue; Aufstieg|aufstieg; Praxisanleiter|praxisanleit; Fortbildung|fortbildung; Aktualisierung|aktualis; kurz"}, {"id": "K119", "deck": "l", "q": "Welche Phasen hat eine Gruppenarbeit?", "a": "1. Rollenverteilung: wer moderiert, protokolliert, ist Zeitwächter, präsentiert?\n2. Vorbereitung: Anforderung und Arbeitsauftrag klären, Mittel und Zeitplanung, Aufgabenverteilung.\n3. Durchführung: recherchieren, Informationen clustern und überprüfen, Bearbeitung.\n4. Präsentation: Ergebnisse zusammenfassen.\n5. Feedback und Reflexion.", "kw": "Rollenverteilung|rollen; moderiert|moderier; protokolliert|protokoll; Zeitwächter|zeitwacht; Vorbereitung|vorbereit; Durchführung|durchfuhr; Präsentation|prasentation; Feedback|feedback/ruckmeldung"}, {"id": "K120", "deck": "l", "q": "Wie präsentiere ich richtig?", "a": "Blickkontakt halten, trotz Lampenfieber das Publikum im Blick behalten, eine gute Position wählen, Gestik und Mimik einsetzen, gut vorbereitet sein, Ablenkungen vermeiden, selbstbewusst und frei sprechen (Füllwörter wie „ähm“ vermeiden), das Publikum einbeziehen und mit eigenen Erlebnissen auch emotional ansprechen.", "kw": "Blickkontakt|blick; Lampenfieber|lampenfieber; Gestik|gestik; Mimik|mimik; vorbereitet|vorbereit; Füllwörter|fullwort; Publikum|publikum"}, {"id": "K121", "deck": "l", "q": "Klassische Fehler bei Präsentationen", "a": "Zuhörer nicht auf ihrem Wissensstand abholen, Zusammenhänge nicht erklären, monotone Stimmlage, Nachfragen nicht dulden, permanentes Ablesen, dem Publikum den Rücken zudrehen, kein Methodenwechsel, autoritäres Auftreten, konzeptloses Vorgehen, Vielrednern das Feld überlassen.", "kw": "Wissensstand|wissensstand; monoton|monoton; Nachfragen|nachfrag; Ablesen|ablesen; Rücken|rucken; Methodenwechsel|methodenwechsel; autoritär|autoritar"}, {"id": "K122", "deck": "v", "q": "Nenne die 3 Beobachtungskriterien des Pulses", "a": "1. Pulsfrequenz – Anzahl der Pulsschläge pro Minute\n2. Pulsrhythmus – zeitliche Abfolge der Pulsschläge\n3. Pulsqualität – Art des Pulsschlags, der erfühlt wird (z. B. weich, hart)", "kw": "Pulsfrequenz|frequenz; Anzahl|anzahl; Minute|minute; Pulsrhythmus|rhythmus; Abfolge|abfolge; Pulsqualität|qualitat; weich; hart"}, {"id": "K123", "deck": "v", "q": "Pulsfrequenz: Normwerte nach Alter", "a": "Laut Folie (Zuordnung im Foto leicht unsicher, bitte im Original prüfen):\n• Neugeborene: 140/Min.\n• Kleinkinder: 120/Min.\n• Kinder: 95/Min.\n• Jugendliche: 90/Min.\n• Erwachsene: 70/Min.\n• Ältere Menschen: 80/Min.", "kw": "Neugeborene|neugeboren; 140; Kleinkinder|kleinkind; 120; Kinder|kinder; 95; Jugendliche|jugendlich; 90; Erwachsene|erwachsen; 70; Ältere|altere; 80"}, {"id": "K124", "deck": "v", "q": "Pulsfrequenz und Herzfrequenz – was ist das Pulsdefizit?", "a": "Die Pulsfrequenz stimmt normalerweise mit der Herzfrequenz überein. Ausnahme: das Pulsdefizit. Dabei zieht sich das Herz zwar zusammen, aber nicht jeder Herzschlag kommt als Puls an.", "kw": "Herzfrequenz|herzfrequenz; überein|uberein; Pulsdefizit|defizit; Herz"}, {"id": "K125", "deck": "v", "q": "Bradykardie – Definition und Ursachen", "a": "Verminderte Herzfrequenz: beim Erwachsenen unter 60 Schläge pro Minute.\nPhysiologisch bei: Schlaf/Ruhe, Hungerzustand, gut trainiertem Zustand.\nPathologisch bei: erhöhtem Hirndruck, Reizbildungsstörung, Reizleitungsstörung, Hyperkaliämie, Schilddrüsenunterfunktion, Medikamenten (z. B. Betablocker), Reizung des Nervus vagus.", "kw": "60; Schlaf|schlaf; Ruhe; Hunger|hunger; trainiert|trainiert; Hirndruck|hirndruck; Reizbildung|reizbildung; Reizleitung|reizleitung; Hyperkaliämie|hyperkali; Schilddrüse|schilddruse; Betablocker|blocker; Vagus|vagus"}, {"id": "K126", "deck": "v", "q": "Tachykardie – Definition und Ursachen", "a": "Gesteigerte Herz- bzw. Pulsfrequenz: beim Erwachsenen über 100 Schläge pro Minute.\nPhysiologisch bei: erhöhtem Sauerstoffbedarf (Anstrengung), Anpassung an verringerte Sauerstoffsättigung (Hochgebirgsluft), seelischer Erregung.\nPathologisch bei: krankhaft erhöhtem Stoffwechsel, verringertem Sauerstoffangebot an die Zellen (z. B. Blutverlust, Herzinsuffizienz), Störung des Herzreizleitungssystems, Hypokaliämie, Schmerzen, Medikamenten.", "kw": "100; Anstrengung|anstreng; Sauerstoff|sauerstoff/o2; Hochgebirge|hochgebirg; Erregung|erregung; Stoffwechsel|stoffwechsel; Blutverlust|blutverlust; Herzinsuffizienz|insuffizienz; Hypokaliämie|hypokali; Schmerzen|schmerz; Medikamente|medikament"}, {"id": "K127", "deck": "v", "q": "Wie verändert Fieber den Puls?", "a": "Bei Fieber erhöht sich der Puls: Pro 1 °C Anstieg der Körpertemperatur steigt die Pulsfrequenz um 8 bis 12 Schläge pro Minute.\nBeispiel: 37 °C auf 39 °C = 16 bis 24 Schläge pro Minute mehr.", "kw": "Fieber|fieber; Grad|grad/1; 8; 12; Schläge|schlag; 16; 24"}, {"id": "K128", "deck": "v", "q": "Pulsrhythmus – Definition und Sinusrhythmus", "a": "Pulsrhythmus = zeitliche Abfolge der Pulswellen (Herzschläge).\nSinusrhythmus (physiologisch): Bei Gesunden liegen zwischen den Pulswellen etwa gleiche Zeiträume (rhythmischer Puls). Bei Kindern und Jugendlichen ist atemabhängige Schwankung normal: beim Einatmen steigt die Frequenz, beim Ausatmen sinkt sie (respiratorische Arrhythmie).", "kw": "zeitliche|zeit; Abfolge|abfolge; Sinusrhythmus|sinus; gleiche|gleich; Einatmung|einatm; Ausatmung|ausatm; respiratorisch|respirator"}, {"id": "K129", "deck": "v", "q": "Was sind Extrasystolen?", "a": "Extrasystolen (kurz ES) sind Herzschläge, die außerhalb des regulären Grundrhythmus auftreten. Vereinzelte ES haben in der Regel keinen Krankheitswert. Mehrere hintereinander haben Behandlungsbedarf.", "kw": "Extrasystole|extrasystol; außerhalb|ausserhalb; Grundrhythmus|grundrhythmus; vereinzelt|vereinzelt; hintereinander|hintereinander; Behandlung|behandlung"}, {"id": "K130", "deck": "v", "q": "Was ist eine Arrhythmie?", "a": "Unregelmäßiger Pulsrhythmus: Herzrhythmusstörung mit unregelmäßigen Zeitabständen zwischen den Herzmuskelkontraktionen.\n• mit zu schneller Herzfrequenz = Tachyarrhythmie\n• mit zu langsamer Herzfrequenz = Bradyarrhythmie\nUrsachen: Herzerkrankungen, Elektrolytverschiebungen, Hormonstörungen (speziell der Schilddrüse).", "kw": "unregelmäßig|unregelmass; Tachyarrhythmie|tachyarrhythm; Bradyarrhythmie|bradyarrhythm; Herzerkrankung|herzerkrank; Elektrolyt|elektrolyt; Schilddrüse|schilddruse"}, {"id": "K131", "deck": "v", "q": "Pulsqualität: Härte und Füllung", "a": "Spannung/Härte: grobe Beobachtung des systolischen Drucks. Hart = hoher Blutdruck, weich = niedriger Blutdruck.\nFüllung/Größe hängt ab von: der Blutmenge im Gefäß, der Kontraktionskraft des Herzens und der Elastizität der Gefäße.", "kw": "hart; hoher|hoch; weich; niedrig; Blutmenge|blutmenge; Kontraktionskraft|kontraktion; Elastizität|elastizit"}, {"id": "K132", "deck": "v", "q": "Großer, kleiner und fadenförmiger Puls", "a": "• Großer Puls: stark und hart, z. B. bei Hypertonie oder Arteriosklerose.\n• Kleiner Puls: schlecht gefüllt, z. B. bei Hypotonie, Blutverlust, Herzinsuffizienz oder Fieber.\n• Fadenförmiger Puls: klein, schnell und schlecht messbar, z. B. beim Schock.", "kw": "groß|gross; Hypertonie|hyper; klein; schlecht gefüllt|gefullt; Hypotonie|hypo; fadenförmig|faden; Schock|schock"}, {"id": "K133", "deck": "s", "q": "Der 6-schrittige Pflegeprozess", "a": "1. Informationen sammeln\n2. Probleme und Ressourcen erkennen\n3. Ziele festlegen\n4. Maßnahmen planen\n5. Maßnahmen durchführen\n6. Evaluation (Beurteilung)\nWichtig: Dein Arbeitsblatt dazu enthält absichtlich Fehler. Diese Reihenfolge ist die gängige Fachlehre. Bitte mit der Lehrkraft abgleichen.", "kw": "Informationen|information; Probleme|problem; Ressourcen|ressource; Ziele|ziel; planen|plan; durchführen|durchfuhr; Evaluation|evaluation/beurteil"}, {"id": "K134", "deck": "s", "q": "Der 4-schrittige Pflegeprozess", "a": "1. Informationssammlung (Pflegeanamnese)\n2. Pflegeprobleme und Ressourcen erkennen\n3. Pflegeziele und Maßnahmen planen\n4. Durchführung und Evaluation\nWichtig: Reihenfolge aus den Überschriften deines Arbeitsblatts rekonstruiert (der Text dort ist absichtlich durcheinander). Bitte mit der Lehrkraft abgleichen.", "kw": "Informationssammlung|informationssammlung/anamnese; Probleme|problem; Ressourcen|ressource; Ziele|ziel; Maßnahmen|massnahme; Durchführung|durchfuhr; Evaluation|evaluation"}, {"id": "K135", "deck": "s", "q": "Was bedeutet evidenzbasierte Pflege (EBN)?", "a": "Evidence-based Nursing: evidenzbasierte Verfahren zur objektiven Beurteilung pflegerischer Maßnahmen. Ziel: Pflegebedürftigen die beste und wirksamste Pflege zukommen zu lassen. Die Methoden sind denen der Medizin angelehnt.", "kw": "Evidenz|eviden; Beurteilung|beurteil; objektiv|objektiv; beste|beste; wirksam|wirksam; Medizin|medizin"}, {"id": "K136", "deck": "s", "q": "Die 6 Schritte der evidenzbasierten Pflege", "a": "1. Auftragsklärung\n2. Fragestellung\n3. Literaturrecherche\n4. Kritische Beurteilung\n5. Implementierung und Adaptation\n6. Evaluation", "kw": "Auftragsklärung|auftragsklar; Fragestellung|fragestellung; Literaturrecherche|literatur; Kritische Beurteilung|kritisch; Implementierung|implementier; Adaptation|adaptation; Evaluation|evaluation"}, {"id": "K137", "deck": "s", "q": "Gewerkschaft und Kammer – was ist der Unterschied?", "a": "Gewerkschaft: freiwillige demokratische Vereinigung von Arbeitnehmern, Gegenspieler der Arbeitgeberverbände, wahrt die Interessen der Arbeitnehmer.\nKammer: auf Landesebene eingerichtete Institution mit vom Staat übertragenen Rechten. Sie klärt berufsinterne Fragen und regelt fachliche und berufliche Belange.", "kw": "Gewerkschaft|gewerkschaft; freiwillig|freiwillig; Arbeitnehmer|arbeitnehmer; Arbeitgeber|arbeitgeber; Kammer|kammer; Landesebene|landesebene; Staat|staat"}, {"id": "K138", "deck": "l", "q": "Wie kommen Informationen ins Langzeitgedächtnis? (limbisches System)", "a": "Das limbische System in der Mitte des Kopfes ist der strenge Wächter: Es prüft jede Neuigkeit (wichtig? gut oder schlecht? witzig?). Vieles wirft es weg. Besonders das, was starke Gefühle auslöst, lässt es durch. Durch Wiederholung werden die Nervenbahnen dicker und es bilden sich neue Synapsen.", "kw": "limbisch|limbisch; Wächter|wachter; prüft|pruft; wichtig|wichtig; Gefühle|gefuhl; Wiederholung|wiederhol; Synapsen|synaps"}, {"id": "K139", "deck": "l", "q": "Gedächtnis-Bild: Bibliothek und Eingangshalle", "a": "Das Langzeitgedächtnis ist wie eine Bibliothek. Das Arbeitsgedächtnis (Kurzzeitgedächtnis) ist die Eingangshalle: ein Zwischenspeicher für Informationen, die man im Moment, aber nicht auf Dauer braucht. Dort verarbeitet man Sinneswahrnehmungen das erste Mal bewusst.", "kw": "Bibliothek|bibliothek; Langzeit|langzeit; Eingangshalle|eingangshalle; Arbeitsgedächtnis|arbeitsgedachtnis/arbeits; Zwischenspeicher|zwischenspeicher"}, {"id": "K140", "deck": "l", "q": "Wie organisiere ich mich beim Lernen?", "a": "• Ordnerstruktur anlegen, geteilt nach CE (Lerneinheit)\n• Unterkategorien mit farbigen Registerkarten\n• Ordnerrückenschilder zum Beschriften, Locher, Heftmaschine, Trennblätter\n• Prüfungen früh planen: kurzfristiges Lernen kostet viel Energie und führt selten zum Erfolg\n• Pufferzeiten, Freizeit und Ausgleich (z. B. Bewegung) einplanen", "kw": "Ordner|ordner; CE|ce; Registerkarten|register; Rückenschilder|ruckenschild; planen|plan; Pufferzeit|puffer; Ausgleich|ausgleich; Bewegung|bewegung"}, {"id": "K141", "deck": "l", "q": "Lerntypen: was ist wissenschaftlich gesichert?", "a": "Im Skript werden vier Lerntypen genannt (visuell, auditiv, kommunikativ, motorisch). Für die Prüfung gibst du das so wieder. Wissenschaftlich ist die Passung „Lerntyp = beste Methode“ aber nicht belegt (Pashler u. a. 2008). Praktisch heißt das: Nutze mehrere Kanäle gleichzeitig – lesen, laut sprechen, aufschreiben.", "kw": "vier|vier/4; visuell|visuell; auditiv|auditiv; kommunikativ|kommunikativ; motorisch|motorisch; nicht belegt|beleg; mehrere Kanäle|kanal; sprechen|sprech; aufschreiben|aufschreib"}, {"id": "K142", "deck": "k", "q": "Was ist Kommunikation?", "a": "Austausch von Informationen zwischen Sender und Empfänger. Der Sender verschlüsselt eine Nachricht, der Empfänger entschlüsselt sie und gibt eine Rückmeldung. Das geschieht verbal, nonverbal und paraverbal.", "kw": "Austausch|austausch; Informationen|information; Sender|sender; Empfänger|empfanger; Nachricht|nachricht; Rückmeldung|ruckmeld; verbal|verbal"}, {"id": "K143", "deck": "k", "q": "Verbal, nonverbal, paraverbal – was ist der Unterschied?", "a": "• Verbal: was gesagt wird, also die Worte.\n• Paraverbal: wie es gesagt wird – Lautstärke, Tempo, Tonfall, Pausen.\n• Nonverbal: alles ohne Worte – Mimik, Gestik, Körperhaltung, Blickkontakt, Nähe und Distanz, Berührung.", "kw": "verbal|verbal; Worte|wort; paraverbal|paraverbal; Lautstärke|lautstarke; Tempo|tempo; Tonfall|tonfall; nonverbal|nonverbal; Mimik|mimik; Gestik|gestik; Körperhaltung|korperhaltung"}, {"id": "K144", "deck": "k", "q": "Das Vier-Seiten-Modell von Schulz von Thun", "a": "Jede Nachricht hat vier Seiten:\n1. Sachinhalt – worüber ich informiere\n2. Selbstkundgabe (Selbstoffenbarung) – was ich von mir zeigen\n3. Beziehung – was ich von dir halte und wie wir zueinander stehen\n4. Appell – was ich bei dir erreichen möchte\nMerkhilfe: S-S-B-A.", "kw": "Sachinhalt|sach; Selbstkundgabe|selbst; Beziehung|beziehung; Appell|appell; vier|vier/4"}, {"id": "K145", "deck": "k", "q": "Vier-Seiten-Modell: Beispiel „Die Klingel geht schon wieder!“", "a": "• Sachinhalt: Die Klingel läutet.\n• Selbstkundgabe: Ich bin gestresst.\n• Beziehung: Du solltest dich besser kümmern.\n• Appell: Geh bitte hin.\nDer Empfänger hört mit vier Ohren und versteht oft etwas anderes, als der Sender meint.", "kw": "Sachinhalt|sach; Klingel|klingel; Selbstkundgabe|selbst; gestresst|stress; Beziehung|beziehung; Appell|appell; vier Ohren|ohren"}, {"id": "K146", "deck": "k", "q": "Die fünf Axiome von Watzlawick", "a": "1. Man kann nicht nicht kommunizieren.\n2. Jede Kommunikation hat einen Inhalts- und einen Beziehungsaspekt.\n3. Kommunikation wird durch Interpunktion gegliedert (Ursache und Wirkung werden unterschiedlich gesehen).\n4. Es gibt digitale (verbale) und analoge (nonverbale) Kommunikation.\n5. Kommunikation ist symmetrisch oder komplementär.", "kw": "nicht nicht|nicht; Inhalt|inhalt; Beziehung|beziehung; Interpunktion|interpunktion; digital|digital; analog|analog; symmetrisch|symmetr; komplementär|komplement"}, {"id": "K147", "deck": "k", "q": "Was bedeutet „Man kann nicht nicht kommunizieren“?", "a": "Auch Schweigen, Wegschauen oder eine abweisende Körperhaltung sind Kommunikation. In der Pflege sendet jedes Verhalten eine Botschaft, auch wenn ich nichts sage.", "kw": "Schweigen|schweig; Verhalten|verhalt; Körperhaltung|korperhaltung; Botschaft|botschaft; Pflege|pflege"}, {"id": "K148", "deck": "k", "q": "Die Grundhaltungen nach Carl Rogers", "a": "Klientenzentrierte (personenzentrierte) Gesprächsführung mit drei Grundhaltungen:\n1. Empathie – einfühlendes Verstehen\n2. Wertschätzung – bedingungslose Akzeptanz\n3. Echtheit (Kongruenz) – ehrlich und stimmig sein\nMerkhilfe: E-W-E.", "kw": "Rogers|rogers; Empathie|empath; einfühlend|einfuhl; Wertschätzung|wertschatz; Akzeptanz|akzept; Echtheit|echt; Kongruenz|kongruenz; drei|drei/3"}, {"id": "K149", "deck": "k", "q": "Was ist aktives Zuhören?", "a": "Dem Gegenüber ungeteilte Aufmerksamkeit schenken: Blickkontakt halten, nicht unterbrechen, mit eigenen Worten wiederholen (Paraphrasieren), Gefühle ansprechen („Das macht Ihnen Sorgen?“) und gezielt nachfragen.", "kw": "Aufmerksamkeit|aufmerksam; Blickkontakt|blick; unterbrechen|unterbrech; Paraphrasieren|paraphras/wiederhol; Gefühle|gefuhl; nachfragen|nachfrag"}, {"id": "K150", "deck": "k", "q": "Gewaltfreie Kommunikation nach Rosenberg: die 4 Schritte", "a": "1. Beobachtung – beschreiben, ohne zu bewerten\n2. Gefühl – was ich dabei fühle\n3. Bedürfnis – was mir wichtig ist\n4. Bitte – eine konkrete Bitte formulieren\nMerkhilfe: B-G-B-B.", "kw": "Beobachtung|beobacht; Gefühl|gefuhl; Bedürfnis|bedurfnis; Bitte|bitte; bewerten|bewert; Rosenberg|rosenberg"}, {"id": "K151", "deck": "k", "q": "Welche ethischen Prinzipien gibt es in der Pflege?", "a": "Nach Beauchamp und Childress vier Prinzipien:\n1. Autonomie (Selbstbestimmung)\n2. Nichtschaden\n3. Fürsorge (Wohltun)\n4. Gerechtigkeit", "kw": "Autonomie|autonom; Selbstbestimmung|selbstbestimm; Nichtschaden|nichtschad/schaden; Fürsorge|fursorge; Wohltun|wohltun; Gerechtigkeit|gerecht; vier|vier/4"}, {"id": "K152", "deck": "k", "q": "Was beeinflusst die Kommunikation in der Pflege?", "a": "Störungen und Einflussfaktoren: Zeitdruck und Lärm, Sprach- und Kulturunterschiede, Hör- oder Sehbehinderung, Schmerzen, Angst und Stimmung, Demenz, fehlendes Vertrauen, Hierarchie.", "kw": "Zeitdruck|zeit; Lärm|larm; Sprache|sprach; Kultur|kultur; Hörbehinderung|hor; Schmerzen|schmerz; Angst|angst; Demenz|demenz; Vertrauen|vertrau"}, {"id": "K153", "deck": "k", "q": "Was ist Stress? Eustress und Distress", "a": "Stress ist die körperliche und psychische Reaktion auf eine Belastung (Stressor). Eustress ist positiver Stress, der motiviert und leistungsfähig macht. Distress ist negativer Stress, der überfordert und auf Dauer krank machen kann.", "kw": "Reaktion|reaktion; Belastung|belast; Stressor|stressor; Eustress|eustress; positiv|positiv; Distress|distress; negativ|negativ; überfordert|uberford"}, {"id": "K154", "deck": "k", "q": "Was ist Burnout?", "a": "Ein Zustand tiefer Erschöpfung durch lang anhaltende berufliche Überlastung. Nach Maslach: emotionale Erschöpfung, Distanzierung (Depersonalisation) und das Gefühl verminderter Leistungsfähigkeit. Phasenmodelle dazu sind Lehrbuchmodelle und wissenschaftlich schwach gestützt.", "kw": "Erschöpfung|erschopf; Überlastung|uberlast; Maslach|maslach; Distanz|distanz; Depersonalisation|depersonal; Leistung|leistung"}, {"id": "K155", "deck": "k", "q": "Was hilft gegen Überforderung und Stress im Pflegealltag?", "a": "Pausen einhalten, Aufgaben priorisieren, im Team um Hilfe bitten, Grenzen setzen und Nein sagen, Ausgleich durch Bewegung und Schlaf, Gespräche mit Kolleginnen und Anleitung, Fortbildungen nutzen.", "kw": "Pausen|pause; priorisieren|prioris; Team|team; Hilfe|hilfe; Grenzen|grenze; Bewegung|bewegung; Schlaf|schlaf"}, {"id": "F001", "deck": "f", "q": "Fall 1: Worum geht es bei Frau Blume?", "a": "Die Pflegefachassistentin Marie arbeitet den neuen Auszubildenden Nico an seinem ersten Tag ein. Die Bewohnerin Frau Blume hat Sprachschwierigkeiten, möchte lange baden statt duschen und akzeptiert nur weibliche Pflegekräfte. Marie beschwert sich über den Zeitverlust. Nico will sofort Praxisanleiter werden, Marie bremst ihn.", "kw": "Marie|marie; Nico|nico; baden|bad; weibliche|weiblich/frauen; Sprache|sprach", "fall": 1}, {"id": "F002", "deck": "f", "q": "Fall 1: Welche Kommunikationstechnik steht bei Frau Blume im Vordergrund?", "a": "Die nonverbale Kommunikation. Frau Blume fehlen die Worte, deshalb zeigt sie mit Gestik, was sie möchte.\nVerbal: Verständigung über gesprochene oder geschriebene Sprache.\nNonverbal: Verständigung ohne Worte, zum Beispiel Mimik, Gestik, Körpersprache.", "kw": "nonverbal|nonverbal/ohne worte; Gestik|gestik/zeigt; Mimik|mimik/körpersprache; verbal|verbal/sprache", "fall": 1}, {"id": "F003", "deck": "f", "q": "Fall 1: Welche Artikel der Pflege-Charta passen zu Frau Blume?", "a": "Artikel 1: Selbstbestimmung.\nArtikel 3: Privatheit und Intimsphäre.\nArtikel 4: Pflege nach individuellen Bedürfnissen.\nBegründung: Frau Blume darf das Baden dem Duschen vorziehen. Nur weibliche Pflegekräfte schützen ihre Intimsphäre. Ihre Wünsche gehen Maries Zeitdruck vor.", "kw": "Artikel 1|eins/1/selbstbestimm; Artikel 3|drei/3/privat/intim; Artikel 4|vier/4/individuell/bedürf", "fall": 1}, {"id": "F004", "deck": "f", "q": "Fall 1: Was unterscheidet Fortbildung und Weiterbildung, und warum kann Nico noch keine Weiterbildung machen?", "a": "Fortbildung: frischt vorhandenes Wissen für den aktuellen Beruf auf, zum Beispiel neue Hygieneregeln.\nWeiterbildung: führt zu einer höheren, neuen Qualifikation, zum Beispiel Praxisanleiter.\nNico ist erst am ersten Ausbildungstag. Eine Weiterbildung setzt eine abgeschlossene Berufsausbildung voraus.", "kw": "Fortbildung|fortbild/auffrisch; Weiterbildung|weiterbild/höher/qualifik; abgeschlossene Ausbildung|abgeschloss/ausbildung/erst", "fall": 1}, {"id": "F005", "deck": "f", "q": "Fall 2: Worum geht es bei Frau Mischke?", "a": "Frau Mischke hatte einen Schlaganfall und kann schlecht sprechen. Sie ist Muslimin und möchte bei der Körperpflege nur von Frauen betreut werden. Die Auszubildende Nina ist genervt, weil das viel Zeit kostet.", "kw": "Schlaganfall|schlaganfall/apoplex; Muslimin|muslim/religion; Frauen|frau/weiblich; Nina|nina", "fall": 2}, {"id": "F006", "deck": "f", "q": "Fall 2: Erläutere die drei Grundhaltungen nach Carl Rogers.", "a": "1. Empathie: Mitgefühl.\n2. Akzeptanz: Wertschätzung und Respekt.\n3. Kongruenz: Echtheit und Ehrlichkeit.\nBegründung: So fühlt sich der Patient verstanden und sicher.", "kw": "Empathie|empath/mitgefühl/einfühl; Akzeptanz|akzept/wertschätz/respekt; Kongruenz|kongruen/ehrlich/echt", "fall": 2}, {"id": "F007", "deck": "f", "q": "Fall 2: Was besagt Artikel 1 des Grundgesetzes und was folgt daraus für Frau Mischke?", "a": "Wörtlich: „Die Würde des Menschen ist unantastbar.“\nWir müssen jeden Menschen respektieren, also auch die Religion und die Wünsche von Frau Mischke.", "kw": "Würde|würde; unantastbar|unantastbar; respektieren|respekt/achten; Religion|religion/wünsch", "fall": 2}, {"id": "F008", "deck": "f", "q": "Fall 2: Was bedeutet lebenslanges Lernen und warum ist es wichtig?", "a": "Man lernt im Beruf immer weiter, auch nach der Schule.\nBegründung: In der Pflege ändert sich vieles. Durch Lernen macht man weniger Fehler und kann später Verantwortung übernehmen.", "kw": "immer weiter|immer/weiter/ständig; nach der Schule|schule/beruf; Fehler|fehler; Verantwortung|verantwort; ändert|änder/neu", "fall": 2}, {"id": "F009", "deck": "f", "q": "Fall 3: Worum geht es bei Andreas im ambulanten Pflegedienst?", "a": "Andreas macht ein Praktikum beim Pflegedienst Sonnenschein. Sein Ausbilder Miro erklärt ihm die Grundbedürfnisse von Menschen und zeigt ihm, wie man richtig kommuniziert.", "kw": "Andreas|andreas; Sonnenschein|sonnenschein; Miro|miro; Grundbedürfnisse|bedürfn; kommuniziert|kommuni", "fall": 3}, {"id": "F010", "deck": "f", "q": "Fall 3: Nenne die fünf Stufen der Bedürfnispyramide nach Maslow.", "a": "1. Körperliche Bedürfnisse, zum Beispiel Essen und Trinken.\n2. Sicherheit.\n3. Soziale Bedürfnisse, zum Beispiel Kontakt und Liebe.\n4. Anerkennung.\n5. Selbstverwirklichung.\nBegründung: Ohne Essen, Sicherheit und sozialen Kontakt wird ein Mensch schnell krank, körperlich oder seelisch.", "kw": "körperlich|körper/essen/trink/physiolog; Sicherheit|sicherheit; sozial|sozial/kontakt/liebe; Anerkennung|anerkenn/wertschätz; Selbstverwirklichung|selbstverwirk", "fall": 3}, {"id": "F011", "deck": "f", "q": "Fall 3: Erkläre das Modell der vier Ohren nach Schulz von Thun.", "a": "Jede Nachricht hat vier Seiten:\n1. Sachohr: Fakten.\n2. Beziehungsohr: Beziehung.\n3. Selbstoffenbarung: Gefühle.\n4. Appellohr: Aufforderung.\nBegründung: Wer alle vier Seiten beachtet, vermeidet Missverständnisse und Streit mit Patienten.", "kw": "Sachohr|sach/fakt; Beziehung|bezieh; Selbstoffenbarung|selbstoffenbar/gefühl; Appell|appell/aufforder", "fall": 3}, {"id": "F012", "deck": "f", "q": "Fall 3: Nenne die drei Phasen der Prüfungsvorbereitung.", "a": "1. Vorbereitungsphase: planen.\n2. Lernphase: Wissen aneignen.\n3. Kontrollphase: überprüfen.\nSelbstreflexion: Lernen mit Karteikarten und gutem Zeitplan vermeidet Stress.", "kw": "Vorbereitung|vorbereit/plan; Lernphase|lernphase/lernen/aneign; Kontrolle|kontroll/überprüf", "fall": 3}, {"id": "F013", "deck": "f", "q": "Fall 4: Worum geht es bei Ania?", "a": "Ania ist bei einem neuen Pflegedienst. Ihr Ausbilder Thomas zeigt ihr, wie man die Pflege genau plant.", "kw": "Ania|ania/anja; Thomas|thomas; Pflegedienst|pflegedienst; plant|plan", "fall": 4}, {"id": "F014", "deck": "f", "q": "Fall 4: Nenne die vier Schritte des Pflegeprozesses.", "a": "1. Informationssammlung: wichtige Daten über den Patienten sammeln, zum Beispiel Krankheiten.\n2. Pflegeplanung: genau aufschreiben, wie wir helfen.\n3. Durchführung.\n4. Auswertung.", "kw": "Informationssammlung|information/daten/samml; Planung|plan; Durchführung|durchführ; Auswertung|auswert/evaluat", "fall": 4}, {"id": "F015", "deck": "f", "q": "Fall 4: Nenne drei positive Faktoren für Kommunikation.", "a": "1. Aktives Zuhören.\n2. Augenkontakt.\n3. Eine ruhige Umgebung ohne Lärm.\nBegründung: Gute Gespräche geben dem Patienten Sicherheit, und wir verstehen besser, was er braucht.", "kw": "Zuhören|zuhör; Augenkontakt|auge/blick; ruhige Umgebung|ruhig/lärm/umgebung", "fall": 4}, {"id": "F016", "deck": "f", "q": "Fall 4: Nenne je zwei Beispiele für Fortbildung und Weiterbildung.", "a": "Fortbildung (Wissen für den jetzigen Beruf auffrischen): Kurs in Erster Hilfe, Hygieneschulung.\nWeiterbildung (für eine höhere Position): Stationsleitung, Wundexpertin.", "kw": "Erste Hilfe|erste hilfe/hilfe; Hygieneschulung|hygien; Stationsleitung|stationsleit/leitung; Wundexpertin|wund", "fall": 4}, {"id": "F017", "deck": "f", "q": "Fall 5: Worum geht es im Akutkrankenhaus?", "a": "Andreas hat seinen ersten Tag auf der Kardiologie im Krankenhaus. Sein Ausbilder Christian spricht mit ihm über Ethik, also Regeln in der Pflege, und über Motivation.", "kw": "Andreas|andreas; Kardiologie|kardiolog/herz; Christian|christian; Ethik|ethik/regeln; Motivation|motiv", "fall": 5}, {"id": "F018", "deck": "f", "q": "Fall 5 und 6: Nenne die vier Aufgaben aus dem Ethikkodex des ICN.", "a": "1. Gesundheit fördern.\n2. Krankheit verhüten.\n3. Gesundheit wiederherstellen.\n4. Leiden lindern.\nBegründung: Das sind die wichtigsten Regeln, um Patienten sicher, gerecht und moralisch richtig zu pflegen.", "kw": "fördern|förder; verhüten|verhüt/vorbeug; wiederherstellen|wiederherstell; lindern|linder", "fall": 5}, {"id": "F019", "deck": "f", "q": "Fall 5: Erkläre intrinsische und extrinsische Motivation mit Beispielen.", "a": "Intrinsisch: kommt von innen, zum Beispiel Spaß an der Arbeit oder der Wunsch, Menschen zu helfen.\nExtrinsisch: kommt von außen, zum Beispiel Geld, Lob oder ein guter Abschluss.", "kw": "innen|innen/intrinsisch; außen|außen/aussen/extrinsisch; Spaß|spaß/helfen; Geld|geld/lob/abschluss", "fall": 5}, {"id": "F020", "deck": "f", "q": "Fall 5: Warum helfen die drei Eigenschaften nach Carl Rogers dem Patienten?", "a": "Empathie, Akzeptanz und Kongruenz sorgen dafür, dass sich der Patient respektiert fühlt und besser gesund werden kann.", "kw": "Empathie|empath; Akzeptanz|akzept; Kongruenz|kongruen; respektiert|respekt/gesund", "fall": 5}, {"id": "F021", "deck": "f", "q": "Fall 6: Worum geht es im zweiten Teil im Krankenhaus?", "a": "Andreas spricht weiter mit seinem Ausbilder Christian. Sie lernen die verschiedenen Arten der Kommunikation und sprechen darüber, was Stress mit dem Körper macht.", "kw": "Andreas|andreas; Christian|christian; Kommunikation|kommunik; Stress|stress", "fall": 6}, {"id": "F022", "deck": "f", "q": "Fall 6: Erkläre verbale, nonverbale und paraverbale Kommunikation mit Beispielen.", "a": "Verbal: das gesprochene Wort, zum Beispiel Gespräch führen, erklären, fragen.\nNonverbal: Körpersprache, zum Beispiel Lächeln, Augenkontakt, Nicken.\nParaverbal: wie man spricht, zum Beispiel Lautstärke, Sprechtempo, freundlicher Tonfall.", "kw": "verbal Wort|wort/gespräch/sprech; nonverbal Körpersprache|körpersprache/lächeln/nicken; paraverbal|paraverbal/lautstärke/tonfall/tempo", "fall": 6}, {"id": "F023", "deck": "f", "q": "Fall 6: Was ist positiver und negativer Stress?", "a": "Positiver Stress heißt Eustress: macht wach und motiviert.\nNegativer Stress heißt Distress: überfordert und macht Angst.\nBegründung: Negativer Stress macht den Körper krank, zum Beispiel durch Schlafprobleme oder hohen Blutdruck.", "kw": "Eustress|eustress/positiv; Distress|distress/negativ; motiviert|motiv/wach; überfordert|überford/angst; krank|krank/schlaf/blutdruck", "fall": 6}, {"id": "F024", "deck": "f", "q": "Wer ist in welchem Fall Ausbilder oder Anleiterin?", "a": "Fall 1: Marie (Pflegefachassistentin) leitet Nico an.\nFall 3: Miro beim Pflegedienst Sonnenschein.\nFall 4: Thomas leitet Ania an.\nFall 5 und 6: Christian im Krankenhaus.", "kw": "Marie|marie; Miro|miro; Thomas|thomas; Christian|christian", "fall": 0}, {"id": "H001", "deck": "h", "q": "Was bedeutet Hygiene?", "a": "Die Lehre von der Verhütung von Krankheiten und vom Erhalten, Fördern und Festigen der Gesundheit. Sie bezieht sich auf Mensch, Gesellschaft und Umwelt. Pflegekräfte sind verpflichtet, Hygieneregeln einzuhalten.", "kw": "Verhütung|verhüt/vorbeug; Krankheiten|krankheit; Gesundheit|gesund; verpflichtet|pflicht/regeln"}, {"id": "H002", "deck": "h", "q": "Welche Persönlichkeiten prägten die Hygiene?", "a": "Ignaz Semmelweis: Händedesinfektion, „Retter der Mütter“.\nFlorence Nightingale: Begründerin der modernen Krankenpflege und Krankenhaushygiene.\nJoseph Lister: Desinfektion mit Karbol vor Operationen.\nRobert Koch: bewies den Zusammenhang zwischen Mikroorganismen und Infektionskrankheiten.\nLouis Pasteur: Pasteurisieren.\nAlexander Fleming: entdeckte 1928 das Penicillin.", "kw": "Semmelweis|semmelweis; Nightingale|nightingale; Lister|lister; Koch|koch; Fleming|fleming/penicillin; Pasteur|pasteur"}, {"id": "H003", "deck": "h", "q": "Welche Aufgabengebiete hat die Hygiene?", "a": "Individualhygiene (Gesundheit des Einzelnen), Lebensmittelhygiene, Umwelthygiene, Arbeitshygiene und Krankenhaushygiene bzw. Hygiene in Pflegeeinrichtungen (Vorbeugung, Erfassung und Kontrolle nosokomialer Infektionen).", "kw": "Individualhygiene|individ/persönl; Lebensmittel|lebensmittel; Umwelt|umwelt; Arbeit|arbeit; Krankenhaus|krankenhaus/pflegeeinricht"}, {"id": "H004", "deck": "h", "q": "Welche Merkmale haben Bakterien?", "a": "Einzeller ohne festen Zellkern, Erbgut liegt frei im Zellplasma, keine Zellorganellen, teilen sich schnell, können Erbgut weitergeben (zum Beispiel Resistenzen), im Lichtmikroskop sichtbar, können Gifte (Toxine) bilden. Viele Bakterien sind nützlich, zum Beispiel Darmflora und Hautflora.", "kw": "Einzeller|einzell; Zellkern|zellkern/kern; Lichtmikroskop|lichtmikroskop/mikroskop; Toxine|toxin/gift; Resistenz|resist; nützlich|nützlich/darmflora/hautflora"}, {"id": "H005", "deck": "h", "q": "Was sind Bakteriensporen?", "a": "Ruheformen von Bakterien. Das Bakterium schrumpft und verbraucht nichts. Sporen überleben jahrelang und werden bei besseren Bedingungen wieder aktiv. Beispiel: Tetanus, zum Beispiel in Blumenerde.", "kw": "Ruheform|ruhe/ruheform; jahrelang|jahr/überleb; aktiv|aktiv/beding; Tetanus|tetanus/erde"}, {"id": "H006", "deck": "h", "q": "Welche Merkmale haben Viren?", "a": "Kleinste Krankheitserreger, nur im Elektronenmikroskop sichtbar. Sie bestehen nur aus Erbgut (DNA oder RNA), behüllt oder unbehüllt. Keine Lebewesen, kein eigener Stoffwechsel, brauchen eine Wirtszelle zur Vermehrung. Sie können jahrelang ruhen und bei Abwehrschwäche ausbrechen (zum Beispiel Herpes).", "kw": "kleinste|klein; Elektronenmikroskop|elektronen; Wirtszelle|wirt/zelle; kein Stoffwechsel|stoffwechsel/kein lebewesen; Erbgut|erbgut/dna/rna"}, {"id": "H007", "deck": "h", "q": "Was weißt du über Pilze als Krankheitserreger?", "a": "Pilzbefall heißt Mykose. Pilze vermehren sich durch Sporen, sind überall und brechen meist erst bei günstigen Bedingungen aus. Hautpilze (zum Beispiel Fußpilz, Nagelpilz), Hefepilze (zum Beispiel Candida albicans, Mundsoor) und Schimmelpilze (zum Beispiel Aspergillus in der Lunge). Gelangen sie ins Blut, droht eine Pilzsepsis.", "kw": "Mykose|mykose/pilzbefall; Hautpilz|fußpilz/nagelpilz/haut; Hefe|hefe/candida/soor; Schimmel|schimmel/aspergill"}, {"id": "H008", "deck": "h", "q": "Was sind Parasiten?", "a": "Lebewesen, die auf Kosten eines Wirts leben, zum Beispiel Würmer (Bandwurm), Läuse, Krätzmilben, Hausstaubmilben, Mücken. Zeichen: Juckreiz, Übelkeit, Bauchschmerzen, Fieber. Ursachen: ungewaschenes Obst, nicht durchgegartes Essen, Stiche, Kontakt mit Kot, Haustieren oder befallenen Menschen.", "kw": "Wirt|wirt/kosten; Würmer|wurm/würmer; Läuse|laus/läuse; Milben|milbe/krätz; Juckreiz|juck"}, {"id": "H009", "deck": "h", "q": "Welche Mittel wirken gegen welche Erreger?", "a": "Bakterien: Antibiotika.\nViren: Virostatika.\nPilze: Antimykotika.\nParasiten: Antiparasitika.", "kw": "Antibiotika|antibiot; Virostatika|virostat; Antimykotika|antimykot; Antiparasitika|antiparasit"}, {"id": "H010", "deck": "h", "q": "Was beachtest du bei Antibiotika und welche Nebenwirkungen sind häufig?", "a": "Antibiotika wirken nur gegen Bakterien. Indikation, Dosierung, Einnahmezeiten und Dauer genau einhalten. Häufige Nebenwirkungen: Durchfall, Übelkeit, Juckreiz, Pilzinfektionen, allergische Reaktionen bis zu Atemnot und allergischem Schock. Die Antibabypille kann schwächer wirken.", "kw": "nur Bakterien|bakter; Dosierung|dosier/zeit/dauer/einhalt; Durchfall|durchfall/übelkeit; Pilz|pilz; Allergie|allerg/schock; Pille|pille"}, {"id": "H011", "deck": "h", "q": "Was ist eine Infektion?", "a": "Das Übertragen, Haftenbleiben, Eindringen und Vermehren von Mikroorganismen im Körper. Eine Infektionskrankheit entsteht, wenn dadurch Krankheitszeichen auftreten.", "kw": "Übertragen|übertrag; Haften|haft; Eindringen|eindring; Vermehren|vermehr"}, {"id": "H012", "deck": "h", "q": "Wovon hängt ab, ob aus einer Infektion eine Krankheit wird?", "a": "Vom Erreger: Art, Menge (Dosis), Pathogenität (kann er überhaupt krank machen) und Virulenz (wie aggressiv er ist).\nVom Menschen (Wirt): Abwehrkraft, Alter, Gesundheitszustand, Schutzimpfungen.", "kw": "Menge|menge/dosis; Pathogenität|pathogen; Virulenz|virulen/aggressiv; Abwehr|abwehr/immun; Alter|alter; Impfung|impf"}, {"id": "H013", "deck": "h", "q": "Was ist die Infektionskette?", "a": "Der Weg eines Erregers: Infektionsquelle, Übertragungsweg und Empfänger mit seiner Eintrittspforte. Unterbricht man ein Glied der Kette, gibt es keine Infektion.", "kw": "Quelle|quelle; Übertragungsweg|übertrag/weg; Eintrittspforte|eintritt/pforte/empfäng; unterbrechen|unterbrech"}, {"id": "H014", "deck": "h", "q": "Welche Eintrittspforten für Erreger gibt es?", "a": "Haut (perkutan), Schleimhaut, Verdauungstrakt (enteral), Atemwege (inhalativ), Harnwege und Geschlechtsorgane (urogenital) und über die Plazenta auf das ungeborene Kind (intrauterin).", "kw": "Haut|haut/perkutan; Schleimhaut|schleimhaut; Verdauung|verdau/darm/enteral/mund; Atemwege|atem/inhalat/lunge; Harnwege|harn/urogenital; Plazenta|plazenta/ungeboren"}, {"id": "H015", "deck": "h", "q": "Nenne die fünf klassischen Entzündungszeichen.", "a": "Rötung (Rubor), Überwärmung (Calor), Schmerz (Dolor), Schwellung (Tumor) und eingeschränkte Funktion (Functio laesa).", "kw": "Rötung|rötung/rot/rubor; Überwärmung|wärm/warm/calor; Schmerz|schmerz/dolor; Schwellung|schwell/tumor; Funktion|funktion"}, {"id": "H016", "deck": "h", "q": "Was ist der Unterschied zwischen endogener und exogener Infektion?", "a": "Exogen: Der Erreger kommt von außen.\nEndogen: Körpereigene Keime lösen die Infektion aus, weil sie an die falsche Stelle gelangen, zum Beispiel Darmkeime in den Harnwegen.", "kw": "außen|außen/aussen/exogen; körpereigen|körpereigen/eigene/endogen; falsche Stelle|falsch/stelle/darmkeim/harnweg"}, {"id": "H017", "deck": "h", "q": "Welche Übertragungswege gibt es?", "a": "Am häufigsten: Kontaktinfektion, direkt von Mensch zu Mensch oder indirekt über Hände und Gegenstände (Schmierinfektion).\nTröpfcheninfektion durch Niesen, Husten, Sprechen.\nAerogene Infektion durch kleine, schwebende Aerosole.\nParenteral durch Infusionen, Transfusionen oder Stichverletzungen.\nAußerdem Lebensmittel und Wasser, Blut, sexuelle Übertragung und Vektoren wie Mücken.", "kw": "Kontakt|kontakt/schmier/hände; Tröpfchen|tröpfchen/husten/niesen; Aerosole|aerosol/aerogen/luft; parenteral|parenteral/stich/blut/infusion; Lebensmittel|lebensmittel/wasser/essen"}, {"id": "H018", "deck": "h", "q": "Was ist eine nosokomiale Infektion?", "a": "Eine Infektion, die im Krankenhaus oder in einer Pflegeeinrichtung entsteht, frühestens 48 bis 72 Stunden nach der Aufnahme. Sie ist die häufigste Komplikation. Folgen: höhere Kosten, mehr Pflegeaufwand, längerer Aufenthalt, im schlimmsten Fall der Tod.", "kw": "Krankenhaus|krankenhaus/klinik/einricht; 48 Stunden|48/72/stunden/tage; Komplikation|komplikat/folgen/kosten"}, {"id": "H019", "deck": "h", "q": "Welche Maßnahmen gehören zur Standardhygiene?", "a": "1. Persönliche Hygiene\n2. Händedesinfektion und Händewaschen\n3. Hustenetikette\n4. Berufskleidung und persönliche Schutzkleidung\n5. Laufende Flächendesinfektion\n6. Reinigung der direkten Umgebung des Pflegeempfängers\n7. Schutz vor Stich- und Schnittverletzungen\n8. Sterilisation\nSie gilt immer und für alle Berufsgruppen.", "kw": "persönliche Hygiene|persönlich; Händedesinfektion|hände/desinf; Hustenetikette|husten; Schutzkleidung|schutzkleid/kleidung; Flächendesinfektion|fläche; Stichverletzung|stich/schnitt; Sterilisation|steril"}, {"id": "H020", "deck": "h", "q": "Nenne die fünf Momente der Händedesinfektion.", "a": "1. Vor Patientenkontakt.\n2. Vor einer aseptischen Tätigkeit.\n3. Nach Kontakt mit möglicherweise infektiösem Material.\n4. Nach Patientenkontakt.\n5. Nach Kontakt mit der direkten Patientenumgebung.\nZusätzlich vor dem Anziehen und nach dem Ausziehen von Handschuhen.", "kw": "vor Patientenkontakt|vor/kontakt; aseptisch|asept/steril; infektiös|infekt/material/körperflüss; nach Patientenkontakt|nach; Umgebung|umgebung"}, {"id": "H021", "deck": "h", "q": "Wie führst du die hygienische Händedesinfektion richtig durch?", "a": "Mindestens 3 Milliliter (etwa zwei Hübe) in die trockene, hohle Hand geben. Mindestens 30 Sekunden einreiben, die Hände müssen die ganze Zeit feucht sein. Jede Bewegung mindestens fünfmal: Handfläche auf Handfläche, Handrücken, verschränkte Finger, Fingeraußenseiten, Daumen kreisend, Fingerkuppen kreisend.", "kw": "3 Milliliter|3/drei/milliliter/hübe; trocken|trocken; 30 Sekunden|30/dreißig/sekunden; Daumen|daumen; Fingerkuppen|kuppe/finger"}, {"id": "H022", "deck": "h", "q": "Wann wäschst du die Hände, und warum müssen sie vor der Desinfektion trocken sein?", "a": "Hände waschen (etwa 30 Sekunden, flüssige rückfettende Seife, Einmalhandtücher): zu Beginn und Ende der Schicht, bei sichtbarer Verschmutzung, nach dem Toilettengang, vor dem Zubereiten von Speisen, nach Kontakt mit Sporenbildnern (vorher desinfizieren).\nWaschen ist kein Ersatz für Desinfektion. Nasse Hände verdünnen das Desinfektionsmittel, es wirkt schlechter.", "kw": "Schicht|schicht/dienst; verschmutzt|schmutz/verschmutz; Toilette|toilette; Sporen|spore; verdünnt|verdünn/wasser/wirkt"}, {"id": "H023", "deck": "h", "q": "Welche Regeln gelten für Hände, Nägel und Schmuck in der Pflege?", "a": "Fingernägel kurz und rund, kein Nagellack, keine künstlichen Nägel oder Gelnägel, kein Schmuck an Händen und Unterarmen, keine Uhr. Bei Entzündungen an Händen oder Nagelbett zum Betriebsarzt. Hautschutz vor, während und nach der Arbeit, Hautpflege nach der Arbeit, Cremes aus Tuben statt Dosen.", "kw": "kurz|kurz; Nagellack|lack/gel/künstlich; Schmuck|schmuck/ring/uhr; Hautschutz|hautschutz/schutz/creme"}, {"id": "H024", "deck": "h", "q": "Was ist der Unterschied zwischen Antisepsis und Asepsis?", "a": "Antisepsis: Desinfektion, die Zahl der Krankheitserreger wird so weit vermindert, dass keine Ansteckung mehr von ihnen ausgeht.\nAsepsis: Keimfreiheit, also steriles Arbeiten ohne Keime.", "kw": "vermindert|vermind/reduz/weniger/desinf; Keimfreiheit|keimfrei/steril/ohne keime"}, {"id": "M001", "deck": "m", "q": "Was gehört zum passiven und was zum aktiven Bewegungsapparat?", "a": "Passiv: Knochen und Gelenke, also das Skelett. Es stützt den Körper und gibt ihm Form.\nAktiv: Skelettmuskeln, Sehnen, Faszien und Schleimbeutel. Sie bewegen den Körper.", "kw": "Knochen|knochen; Gelenke|gelenk; Muskeln|muskel; Sehnen|sehne; stützen|stütz; bewegen|beweg"}, {"id": "M002", "deck": "m", "q": "Wie viele Knochen hat das Skelett und wie wird es eingeteilt?", "a": "206 Knochen.\nKopfskelett (Hirn- und Gesichtsschädel), Rumpfskelett (Wirbelsäule, Brustkorb mit Rippen und Brustbein) und Gliedmaßenskelett (Schultergürtel, Becken, Arme, Beine).", "kw": "206|206/zweihundertsechs; Kopfskelett|kopf; Rumpfskelett|rumpf; Gliedmaßen|gliedma"}, {"id": "M003", "deck": "m", "q": "Welche Gelenkarten sind Schulter, Hüfte und Ellenbogen?", "a": "Schultergelenk und Hüftgelenk sind Kugelgelenke: Bewegung in alle Richtungen.\nDas Ellenbogengelenk ist ein Scharniergelenk: beugen und strecken.\nDas größte Gelenk ist das Kniegelenk.", "kw": "Kugelgelenk|kugel; Scharniergelenk|scharnier; alle Richtungen|richtung; beugen|beug/streck"}, {"id": "M004", "deck": "m", "q": "Warum ist Muskelkraft im Alter so wichtig?", "a": "Sie erhält die Selbstständigkeit im Alltag, senkt die Sturzgefahr, schützt die Gelenke und bremst den Abbau von Knochenmasse. Muskeltraining ist bis ins hohe Alter möglich und nötig.", "kw": "Selbstständigkeit|selbst; Sturz|sturz; Gelenke|gelenk; Knochen|knochen; Training|train/übung"}, {"id": "M005", "deck": "m", "q": "Welche Risiken entstehen durch Immobilität?", "a": "Dekubitus, Thrombose, Kontraktur, Pneumonie, Obstipation, Sturz und Deprivation.", "kw": "Dekubitus|dekubit/druckgeschw; Thrombose|thrombo; Kontraktur|kontraktur/versteif; Pneumonie|pneumon/lungenentz; Obstipation|obstipat/verstopf; Sturz|sturz; Deprivation|depriv/einsam"}, {"id": "M006", "deck": "m", "q": "Was ist eine Kontraktur?", "a": "Eine dauerhafte Versteifung und Verkürzung von Muskeln, Sehnen, Bändern oder Gelenkkapsel. Das Gelenk lässt sich nicht mehr voll bewegen, es entsteht eine Fehlstellung. Ursachen: Bewegungsmangel, Ruhigstellung, Lähmung, Verletzung.", "kw": "Versteifung|steif; Verkürzung|verkürz; Gelenk|gelenk; Bewegungsmangel|bewegungsmangel/ruhig/lähm"}, {"id": "M007", "deck": "m", "q": "Was bedeutet Obstipation?", "a": "Verstopfung: weniger als drei Stuhlgänge pro Woche, harter Stuhl, starkes Pressen oder das Gefühl, nicht vollständig entleert zu sein.", "kw": "Verstopfung|verstopf; selten|selten/drei/weniger; harter Stuhl|hart; Pressen|press"}, {"id": "M008", "deck": "m", "q": "Was ist Deprivation?", "a": "Ein Mangel an Reizen, Zuwendung und sozialen Kontakten. Folgen: Lustlosigkeit, Antriebslosigkeit, Schlafstörungen bis hin zu Depression oder Angst.", "kw": "Mangel|mangel/fehl; Reize|reiz; Kontakte|kontakt/zuwendung/sozial; Depression|depress/antrieb/lustlos"}, {"id": "M009", "deck": "m", "q": "Welche körperlichen Folgen hat lange Bettlägerigkeit?", "a": "Muskelschwund und Schwäche, Gelenksteife bis zur Kontraktur, flache Atmung mit Gefahr der Pneumonie, Thrombose mit Gefahr der Lungenembolie, Dekubitus, Verstopfung.", "kw": "Muskelschwund|muskel; Gelenksteife|gelenk/kontraktur/steif; Pneumonie|pneumon/lunge/atm; Thrombose|thrombo; Dekubitus|dekubit/druck; Verstopfung|verstopf/obstip"}, {"id": "M010", "deck": "m", "q": "Welche psychischen Folgen hat lange Bettlägerigkeit?", "a": "Einsamkeit und Isolation, Depression und Angst, Konzentrations- und Gedächtnisprobleme, das Gefühl für Zeit geht verloren, Gefühl von Hilflosigkeit.", "kw": "Einsamkeit|einsam/isol; Depression|depress; Angst|angst; Konzentration|konzentr/gedächt; Zeitgefühl|zeit"}, {"id": "M011", "deck": "m", "q": "Nenne die fünf Phasen des Mobilitätsprozesses nach Zegelin.", "a": "1. Instabilität (Gangunsicherheit)\n2. Ereignis (zum Beispiel Sturz oder Klinikaufenthalt)\n3. Immobilität im Raum\n4. Ortsfixierung (Ortswechsel nur mit fremder Hilfe)\n5. Bettlägerigkeit", "kw": "Instabilität|instabil; Ereignis|ereignis; Immobilität|immobil; Ortsfixierung|ortsfix/fixier; Bettlägerigkeit|bettläger"}, {"id": "M012", "deck": "m", "q": "Was kennzeichnet die Phase Ortsfixierung nach Zegelin?", "a": "Der Mensch kann den Ort nicht mehr selbstständig wechseln, nur mit fremder Hilfe. Er kann aber noch selbst bestimmen, wohin. Er ist abhängig von Tagesstruktur, Bettzeiten und Rollstuhlzeiten.", "kw": "fremde Hilfe|hilfe; selbstbestimmt|bestimm; Ortswechsel|ort; abhängig|abhängig/tagesstruktur"}, {"id": "M013", "deck": "m", "q": "Was beschreibt der Teufelskreis der Immobilität?", "a": "Ein Ereignis wie Operation oder Sturz schränkt die Bewegung ein. Dadurch bauen Muskeln ab, Gelenke verändern sich, es entstehen Schmerzen. Aufstehen und Gehen werden schwerer, die Sturzgefahr steigt, man bewegt sich noch weniger. Zusätzlich drohen Dekubitus, Thrombose und Kontraktur.", "kw": "Ereignis|ereignis/sturz/operation; Muskelabbau|muskel; Schmerzen|schmerz; weniger Bewegung|weniger/beweg; Sturzgefahr|sturz"}, {"id": "M014", "deck": "m", "q": "Welche Hilfsmittel unterstützen bettlägerige Menschen?", "a": "Druckentlastende Matratze, Pflegebett, Bettgalgen, Betttisch, Rutschbrett und Transferhilfen, Patientenlifter, Toilettenstuhl, Lagerungskissen, Bettpfanne und Urinflasche.", "kw": "Matratze|matratze; Pflegebett|pflegebett; Bettgalgen|galgen; Rutschbrett|rutsch/transfer; Lifter|lift; Toilettenstuhl|toilette"}, {"id": "M015", "deck": "m", "q": "Was bedeutet Prophylaxe und welche drei Stufen gibt es?", "a": "Prophylaxe heißt Vorbeugung.\nPrimärprophylaxe: vor Beginn einer Erkrankung.\nSekundärprophylaxe: nach Beginn einer Erkrankung, um Verschlimmerung zu verhindern.\nTertiärprophylaxe: Vorbeugung von Rückfällen.", "kw": "Vorbeugung|vorbeug; Primär|primär; Sekundär|sekundär; Tertiär|tertiär/rückfall"}, {"id": "M016", "deck": "m", "q": "Nenne mindestens sechs Prophylaxen in der Pflege.", "a": "Sturz, Dekubitus, Thrombose, Pneumonie, Aspiration, Obstipation, Kontraktur, Intertrigo, Soor und Parotitis, Exsikkose und Dehydration, Malnutrition, Zystitis, Infektion, Deprivation.", "kw": "Sturz|sturz; Dekubitus|dekubit; Thrombose|thrombo; Pneumonie|pneumon; Kontraktur|kontraktur; Obstipation|obstip; Intertrigo|intertrigo; Soor|soor; Exsikkose|exsikk/dehydr; Zystitis|zystit/blasenentz"}, {"id": "M017", "deck": "m", "q": "Was ist ein Dekubitus?", "a": "Ein Druckgeschwür, auch Wundliegen genannt: eine örtlich begrenzte Schädigung der Haut und oder des darunterliegenden Gewebes durch Druck oder durch Druck zusammen mit Scherkräften.", "kw": "Druckgeschwür|druckgeschw/wundlieg; Druck|druck; Haut|haut; Gewebe|gewebe; Scherkräfte|scher"}, {"id": "M018", "deck": "m", "q": "Wie entsteht ein Dekubitus?", "a": "Liegt der Druck auf einer Stelle länger über dem Druck in den Kapillaren, wird die Durchblutung gestört. Die Zellen bekommen zu wenig Sauerstoff und Nährstoffe, das Gewebe übersäuert, die Haut rötet sich, Gewebe stirbt ab. Muskeln sind empfindlicher als Haut, deshalb kann ein tiefer Schaden auch unter intakter Haut entstehen.", "kw": "Druck|druck; Kapillaren|kapillar; Durchblutung|durchblut; Sauerstoff|sauerstoff; Rötung|röt/rot"}, {"id": "M019", "deck": "m", "q": "Wer ist besonders dekubitusgefährdet?", "a": "Menschen mit eingeschränkter Bewegung, Lähmungen, Empfindungsstörungen oder Bewusstseinsstörungen, Durchblutungsstörungen, starker Abmagerung (Kachexie) oder starkem Übergewicht, Eiweißmangel, Kortisontherapie, hohem Alter und Inkontinenz.", "kw": "Bewegung|beweg/immobil/lähm; Empfindung|empfind/bewusst; Durchblutung|durchblut; Abmagerung|kachex/mager/untergew/eiweiß; Übergewicht|übergew/adipos; Alter|alt"}, {"id": "M020", "deck": "m", "q": "Wie funktioniert der Fingertest bei einer Hautrötung?", "a": "Etwa drei Sekunden mit dem Zeigefinger auf die gerötete Stelle drücken. Wird die Haut kurz weiß, liegt noch kein Dekubitus vor. Bleibt sie rot, liegt ein Dekubitus der Kategorie 1 vor. Bei gutem Licht durchführen, nicht bei Entzündungen, Wunden oder feuchtigkeitsgereizter Haut.", "kw": "drücken|drück; weiß|weiß/weiss/hell; rot bleibt|rot; Kategorie eins|kategorie/eins/1"}, {"id": "M021", "deck": "m", "q": "Beschreibe die vier Kategorien eines Dekubitus.", "a": "Kategorie 1: nicht wegdrückbare Rötung bei intakter Haut.\nKategorie 2: Teilverlust der Haut, zum Beispiel Blase oder Abschürfung.\nKategorie 3: Verlust aller Hautschichten, Unterhaut geschädigt bis zum Muskel.\nKategorie 4: Zerstörung bis in Muskeln, Knochen, Sehnen oder Gelenkkapsel.", "kw": "Rötung|rötung/rot; Blase|blase/abschürf/teilverlust; Hautschichten|hautschicht/unterhaut; Muskel|muskel; Knochen|knochen/sehne"}, {"id": "M022", "deck": "m", "q": "Welche Maßnahmen gehören zur Dekubitusprophylaxe?", "a": "Bewegung fördern, Druck regelmäßig entlasten und Position wechseln (zum Beispiel 30-Grad-Seitenlage), Weichlagerung oder Wechseldruckmatratze, Haut sauber und trocken halten, pH-neutral reinigen, Wasser-in-Öl-Pflege, auf Ernährung und Trinkmenge achten, Schmerzen behandeln.", "kw": "Bewegung|beweg/mobil; Druckentlastung|druck; Positionswechsel|position/lager/umlager; Haut|haut; Matratze|matratze; Ernährung|ernähr/trink"}, {"id": "M023", "deck": "m", "q": "Welche Hilfsmittel und Mittel sind bei der Dekubitusprophylaxe ungeeignet?", "a": "Felle, Wasserkissen, Watteverbände, Gummiringe und fettige Cremes. Auch alkoholische Produkte und Zinksalben schaden. Wärmflasche oder Eisbeutel nie direkt auf gefährdete Haut.", "kw": "Felle|fell; Wasserkissen|wasser; Watte|watte; Gummiringe|gummi/ring; fettige Cremes|fett/creme"}, {"id": "M024", "deck": "m", "q": "Was ist eine Thrombose?", "a": "Ein Blutgerinnsel (Thrombus), das ein Blutgefäß verengt oder verschließt. Am häufigsten in den tiefen Bein- und Beckenvenen (Phlebothrombose). Größte Gefahr: Löst sich das Gerinnsel, kann es eine Lungenembolie auslösen.", "kw": "Blutgerinnsel|gerinnsel/thrombus; Gefäß|gefäß/vene/ader; Bein|bein; Lungenembolie|lunge/embolie"}, {"id": "M025", "deck": "m", "q": "Was ist die Virchow-Trias?", "a": "Die drei Ursachen einer Thrombose: 1. verlangsamte Blutströmung (zum Beispiel Bettruhe, Gips, Operation), 2. Schaden an der Gefäßwand (Verletzung, Entzündung, Krampfadern), 3. erhöhte Gerinnungsneigung (zum Beispiel Flüssigkeitsmangel, Pille, große Operation).", "kw": "Blutströmung|strömung/langsam/fluss; Gefäßwand|wand; Gerinnung|gerinn"}, {"id": "M026", "deck": "m", "q": "Woran erkennt man eine tiefe Beinvenenthrombose und was tust du?", "a": "Oft kaum Zeichen. Möglich: einseitiges Schwere- und Spannungsgefühl, Schwellung, Überwärmung, Wadenschmerz (stärker beim Anziehen des Fußes oder bei Druck), bläulich-rote Haut, schneller Puls, leichtes Fieber.\nSofort Arzt informieren, Bettruhe einhalten lassen.", "kw": "Schwellung|schwell/dick; Überwärmung|wärm/warm; Schmerz|schmerz/wade; bläulich|blau/bläul/rot; Arzt|arzt; Bettruhe|bettruh/liegen"}, {"id": "M027", "deck": "m", "q": "Woran erkennt man eine Lungenembolie?", "a": "Plötzliche Atemnot, schnelle flache Atmung, Brustschmerz vor allem beim Einatmen, Husten eventuell mit Blut, gestaute Halsvenen, schneller Puls, Blutdruckabfall, Blaufärbung (Zyanose), Schweiß bis zum Schock. Lebensgefahr, sofort Notruf.", "kw": "Atemnot|atemnot/luftnot/luft; Brustschmerz|brust; Husten|husten; Puls|puls/herz; blau|blau/zyan; Notruf|notruf/notarzt/arzt"}, {"id": "M028", "deck": "m", "q": "Welche Maßnahmen gehören zur Thromboseprophylaxe?", "a": "Frühe Mobilisation und Gehen (aktiviert die Muskel-Venen-Pumpe), Bewegungsübungen im Bett, medizinische Thromboseprophylaxestrümpfe oder Kompressionsverband, Beine hochlagern, Atemübungen, genug trinken (etwa 1,5 bis 2 Liter, wenn erlaubt), Medikamente wie Heparin nach ärztlicher Anordnung.", "kw": "Mobilisation|mobilis/gehen/laufen/beweg; Kompression|kompression/strümpf/strumpf; hochlagern|hoch; Atemübungen|atem; trinken|trink; Heparin|heparin/spritze/medikament"}, {"id": "M029", "deck": "m", "q": "Worauf achtest du bei medizinischen Thromboseprophylaxestrümpfen (MTPS)?", "a": "Vor dem Messen 15 bis 20 Minuten liegen lassen, dann Beinlänge (Ferse bis Gesäß) und Umfang von Wade und Oberschenkel messen und die Größe nach Herstellertabelle wählen. Faltenfrei anziehen, gern mit Anziehhilfe. Über das Loch an den Zehen regelmäßig Farbe und Durchblutung prüfen. Zu enge Strümpfe färben die Zehen blau.", "kw": "messen|mess; liegen|lieg; Größe|größe/tabelle; faltenfrei|falte; Zehen|zeh; Durchblutung|durchblut/farbe/blau"}, {"id": "M030", "deck": "m", "q": "Wie funktioniert die Stufenlagerung zur Thromboseprophylaxe?", "a": "Die Beine liegen höher als der Rumpf, die Knie sind leicht gebeugt (etwa 20 Grad), die Fersen liegen frei, alles gut gepolstert. Nicht stärker beugen, sonst knicken die Gefäße in der Leiste ab.", "kw": "Beine|bein; höher|höher/hoch; Knie gebeugt|knie/gebeugt/beug; Fersen frei|ferse"}, {"id": "M031", "deck": "m", "q": "Welche Bewegungsübungen im Bett helfen gegen Thrombose?", "a": "Fußspitzen zur Nase ziehen und wieder strecken (Wadenpumpe), Füße kreisen, Fußsohlen gegen das Bettende drücken, Oberschenkel anspannen, Beine heben, Bettradfahren (nicht nach Bauch-OP und nicht in der Schwangerschaft), tief atmen.", "kw": "Fußspitzen|fuß/zehen; kreisen|kreis; Wade|wade/pump/anspann; Radfahren|rad; atmen|atm"}, {"id": "M032", "deck": "m", "q": "Warum helfen Atemübungen bei der Thromboseprophylaxe?", "a": "Tiefes Einatmen erzeugt einen Unterdruck im Brustkorb und in der großen Hohlvene. Der Sog reicht bis in die Beinvenen, das Blut fließt schneller zurück. Mehrmals täglich vier bis fünf tiefe Atemzüge. Allein reichen Atemübungen nicht.", "kw": "Unterdruck|unterdruck/sog; Brustkorb|brust/thorax; Hohlvene|hohlvene/vene; schneller|schnell/fließ/rückfluss"}, {"id": "P001", "deck": "p", "q": "Warum gilt die Haut als größtes Organ des Menschen?", "a": "Sie hat eine Fläche von etwa 1,5 bis 2 Quadratmetern und wiegt ohne Fett etwa 2,5 bis 3 Kilogramm, mit Fettgewebe fast 10 Kilogramm. Sie trennt Innenwelt und Außenwelt.", "kw": "Quadratmeter|quadrat/meter; Kilogramm|kilo/kg; Fläche|fläche/groß; Innenwelt|innen/außen/grenz"}, {"id": "P002", "deck": "p", "q": "Nenne die Funktionen der Haut.", "a": "Schutz vor Umwelteinflüssen, Formgebung, Sinnesorgan (Berührung, Druck, Wärme, Kälte, Schmerz), Regulation der Körpertemperatur, Aufnahme und Ausscheidung (Schweiß, Talg), Kommunikation und Spiegel der Seele.", "kw": "Schutz|schutz/schütz; Sinnesorgan|sinn/fühl/berühr; Temperatur|temperatur/wärme/schwitz; Ausscheidung|ausscheid/schweiß/aufnahm; Kommunikation|kommunik/seele/gefühl"}, {"id": "P003", "deck": "p", "q": "Beschreibe die drei Schichten der Haut.", "a": "Epidermis (Oberhaut): ohne Blutgefäße, außen Hornschicht, innen Keimschicht, erneuert sich etwa alle vier Wochen.\nDermis (Lederhaut): Bindegewebe mit kollagenen und elastischen Fasern, Gefäßen, Nerven, Schweiß- und Talgdrüsen, Haarwurzeln. Gibt Reißfestigkeit und Elastizität.\nSubkutis (Unterhaut): Fettgewebe als Stoßpuffer, Kälteschutz und Energiespeicher. Hier spritzt man subkutan.", "kw": "Epidermis|epidermis/oberhaut; Dermis|dermis/lederhaut; Subkutis|subkutis/unterhaut; Fett|fett"}, {"id": "P004", "deck": "p", "q": "Was ist der Hydrolipidfilm und warum ist er wichtig?", "a": "Ein Film aus Wasser (aus den Schweißdrüsen) und Fett (aus den Talgdrüsen) auf der Hornschicht. Er ist leicht sauer, pH-Wert um 5 bis 5,5 (Säureschutzmantel). Er hält die Haut geschmeidig, fördert die gesunde Hautflora und hemmt fremde Keime.", "kw": "Wasser|wasser/schweiß; Fett|fett/talg; sauer|sauer/säure; Keime|keim/bakter/flora; geschmeidig|geschmeid/schutz"}, {"id": "P005", "deck": "p", "q": "Was machen die Melanozyten?", "a": "Sie liegen in der Epidermis und bilden Melanin. Melanin gibt der Haut Farbe und schützt die tieferen Schichten vor UV-Licht. Kinder haben weniger Melanin und sind weniger geschützt. Im Alter entstehen durch ungleichmäßige Pigmentbildung Altersflecken.", "kw": "Melanin|melanin/pigment; Farbe|farbe; UV|uv/sonne/licht; Altersflecken|altersfleck/fleck"}, {"id": "P006", "deck": "p", "q": "Welche Hauttypen unterscheidet man bei Erwachsenen?", "a": "Seborrhoische Haut: fettig, viel Talg und Schweiß, grobporig, neigt zu Unreinheiten (etwa die Hälfte der Menschen).\nSebostatische Haut: trocken, wenig Talg, spröde, schuppig, juckt (etwa ein Drittel).\nMischhaut: fettige Gesichtsmitte (T-Zone), trockene Wangen.", "kw": "seborrhoisch|seborrh/fettig; sebostatisch|sebostat/trocken; Mischhaut|misch"}, {"id": "P007", "deck": "p", "q": "Woran erkennst du Altershaut und warum entsteht sie?", "a": "Altershaut ist dünn bis pergamentartig, hat wenig Spannung, wirkt faltig, blass und kühl, ist trocken, schuppig, rissig, juckt und neigt zu Blutergüssen. Ursache: weniger elastische Fasern, weniger Durchblutung, weniger Talg und Schweiß, weniger Wasserbindung und langsamere Erneuerung.", "kw": "dünn|dünn/pergament; trocken|trocken/schupp/riss; Blutergüsse|blutergu/hämatom/einblut; Fasern|faser/elast; Talg|talg/fett/schweiß"}, {"id": "P008", "deck": "p", "q": "Was ist eine Zyanose und wo siehst du sie zuerst?", "a": "Eine bläulich-violette Verfärbung bei zu wenig Sauerstoff im Blut. Gut sichtbar an Lippen, Fingerspitzen, Nägeln, Zehen, Ohrläppchen, Nase und Bindehaut. Betroffene können über Atemnot klagen.", "kw": "bläulich|blau/bläul/violett; Sauerstoff|sauerstoff; Lippen|lippe; Finger|finger/nägel/nagel; Atemnot|atemnot/luft"}, {"id": "P009", "deck": "p", "q": "Was ist ein Ikterus?", "a": "Eine Gelbfärbung durch Gallenfarbstoff (Bilirubin). Krankhaft werden meist zuerst die Lederhaut der Augen (Skleren), dann die Haut gelb. Bei Neugeborenen tritt zwischen dem 3. und 10. Lebenstag oft ein harmloser Ikterus auf. Viele Karotten färben nur die Haut, nicht die Augen.", "kw": "gelb|gelb; Bilirubin|bilirubin/galle; Augen|auge/sklera/skleren; Neugeborene|neugebor/baby"}, {"id": "P010", "deck": "p", "q": "Welche Ursachen haben Hautrötung und Hautblässe?", "a": "Rötung (Hyperämie): natürlich bei Anstrengung, Hitze, Gefühlen; krankhaft bei Fieber, Entzündung, Verbrennung, Bluthochdruck.\nBlässe: natürlich bei Kälte oder Schreck; krankhaft bei niedrigem Blutdruck, Schock, Blutarmut (Anämie) oder Durchblutungsstörungen.", "kw": "Fieber|fieber; Entzündung|entzünd; Hitze|hitze/anstreng; Schock|schock; Anämie|anäm/blutarm; Kälte|kälte/schreck"}, {"id": "P011", "deck": "p", "q": "Was sagt der Hautturgor aus?", "a": "Der Hautturgor ist die Spannung der Haut. Er hängt vom Flüssigkeitsgehalt ab. Niedrig bei Flüssigkeitsmangel (Dehydration): eine hochgezogene Hautfalte bleibt stehen. Erhöht bei Wassereinlagerung (Ödem): Druck hinterlässt eine Delle.", "kw": "Spannung|spannung; Flüssigkeit|flüssig/wasser; Hautfalte|falte; Dehydration|dehydr/austrock; Ödem|ödem/delle"}, {"id": "P012", "deck": "p", "q": "Welche Hautanhangsgebilde gibt es?", "a": "Haare, Nägel, Talgdrüsen, Schweißdrüsen und Duftdrüsen.\nTalg macht die Haut geschmeidig, Schweiß kühlt und ist sauer, Duftdrüsen in Achsel und Schamregion bilden ab der Pubertät den Körpergeruch, Nägel schützen Finger und Zehen.", "kw": "Haare|haar; Nägel|nagel/nägel; Talgdrüsen|talg; Schweißdrüsen|schweiß; Duftdrüsen|duft"}, {"id": "P013", "deck": "p", "q": "Nenne die fünf Prinzipien der Körperpflege.", "a": "1. Individuell nach Bedürfnissen und Wünschen.\n2. Sicher, der Mensch fühlt sich sicher.\n3. Intimsphäre wird gewahrt, Berührung ist angemessen.\n4. Hygieneregeln werden beachtet.\n5. Therapeutische Ziele und Konzepte werden einbezogen.", "kw": "individuell|individ/wünsch/bedürf; sicher|sicher; Intimsphäre|intim/scham; Hygiene|hygien; therapeutisch|therap/ziel"}, {"id": "P014", "deck": "p", "q": "Welche vier Tabuzonen des Körpers unterscheidet man?", "a": "Öffentlicher Bereich: Berührung allgemein erlaubt, zum Beispiel Hände, Hinterkopf.\nHalböffentlicher Bereich: Berührung mit Einverständnis, zum Beispiel Rücken, Unterarme.\nPrivater Bereich: nur Familie und Freunde, zum Beispiel Brust, Gesicht.\nIntimer Bereich: nur die Person selbst oder sehr nahe Menschen, zum Beispiel Hals, Genitalbereich.", "kw": "öffentlich|öffentlich; halböffentlich|halböffentl/halb; privat|privat; intim|intim"}, {"id": "P015", "deck": "p", "q": "Welche Distanzzonen hat der Mensch?", "a": "Intime Zone: bis etwa 60 Zentimeter, nur Partner, Familie, engste Freunde.\nPersönliche Zone: etwa 60 Zentimeter bis gut einen Meter, Freunde und Kollegen.\nSoziale Zone: etwa 1,2 bis 3,6 Meter, Fremde und Verkäufer.\nÖffentliche Zone: mehr als 3,6 Meter.", "kw": "intim|intim; persönlich|persönl; sozial|sozial; öffentlich|öffentl"}, {"id": "P016", "deck": "p", "q": "Wie gehst du mit Berührungen im privaten und intimen Bereich um?", "a": "Den Menschen vorher informieren und die Notwendigkeit erklären, sein Einverständnis einholen, ihn einbeziehen (zum Beispiel seine Hände führen), Reaktionen wie Verkrampfen, Angst oder Abwehr wahrnehmen und das Vorgehen anpassen.", "kw": "informieren|inform/ankünd/erklär; Einverständnis|einverst/erlaub/zustimm; einbeziehen|einbez/hände führ/mitmach; Reaktionen|reaktion/beobacht/wahrnehm"}, {"id": "P017", "deck": "p", "q": "Welche Ziele hat die Körperpflege?", "a": "Den Körper reinigen, Wohlbefinden steigern, Krankheiten vorbeugen, durch aktivierende Pflege die Selbstständigkeit und das Selbstwertgefühl fördern, Wahrnehmung und Kommunikation erhalten oder wiederherstellen.", "kw": "reinigen|reinig/sauber; Wohlbefinden|wohl; vorbeugen|vorbeug/prophyl/krankheit; Selbstständigkeit|selbst/aktivier; Wahrnehmung|wahrnehm/kommunik"}, {"id": "P018", "deck": "p", "q": "Wann wählst du welche Form der Körperpflege?", "a": "Ganzkörperwaschung im Bett: wenn der Mensch sich nicht selbst waschen kann oder darf, zum Beispiel nach einer Operation; schont den Kreislauf.\nUnterstützung im Bett: weitgehend selbstständig, darf aber nicht aufstehen.\nAm Waschbecken: teilweise selbstständig, Mobilisation nutzen.\nDuschen: am angenehmsten, regt den Kreislauf an.", "kw": "Bett|bett; Waschbecken|waschbeck; Duschen|dusch; Kreislauf|kreislauf; Mobilisation|mobilis"}, {"id": "P019", "deck": "p", "q": "Welche Grundsätze gelten bei der Hautreinigung?", "a": "Wasser etwa 34 Grad, bei Neugeborenen etwa 37 Grad. Je wärmer das Wasser, desto mehr wird der Säureschutzmantel zerstört. Keine Reste von Seife oder Reinigungsmitteln auf der Haut lassen. Mittel parfümfrei und ohne Konservierungsstoffe. Seife ist alkalisch und trocknet aus, besser ein pH-neutrales Syndet. Weniger ist mehr.", "kw": "34 Grad|34/vierunddreißig/lauwarm; Säureschutzmantel|säure/schutzmantel; Seife|seife/alkal; Rückstände|rest/rückstand/abspül; parfümfrei|parfüm/duft"}, {"id": "P020", "deck": "p", "q": "Was ist der Unterschied zwischen Öl-in-Wasser und Wasser-in-Öl?", "a": "Öl-in-Wasser-Emulsion: mehr Wasser als Fett, für normale bis fettige Haut.\nWasser-in-Öl-Emulsion: mehr Fett als Wasser, für trockene, beanspruchte und alte Haut.", "kw": "mehr Wasser|mehr wasser/wasseranteil; mehr Fett|mehr fett/fettanteil; fettige Haut|fettig/normal; trockene Haut|trocken/alt"}, {"id": "P021", "deck": "p", "q": "Worauf achtest du bei der Intimpflege der Frau?", "a": "Klares Wasser ohne Zusatz, Sichtschutz, Beine anstellen lassen. Immer von vorn nach hinten wischen, bei den kleinen Schamlippen von innen nach außen. Für jeden Wischvorgang einen neuen Zipfel des Waschlappens. In gleicher Richtung trocken tupfen und Haut und Schleimhaut beobachten. Bei Blasenkatheter immer von der Harnröhre weg waschen.", "kw": "vorn nach hinten|vorn nach hinten/vorne nach hinten/hinten; innen nach außen|innen; Zipfel|zipfel/neue/wechsel; tupfen|tupf/trocken; Katheter|katheter/harnröhre"}, {"id": "P022", "deck": "p", "q": "Worauf achtest du bei der Intimpflege des Mannes?", "a": "Vorhaut zurückziehen, Harnröhrenöffnung und Eichel waschen, abtrocknen und die Vorhaut danach unbedingt wieder ganz über die Eichel ziehen, um eine Paraphimose zu verhindern. Penisschaft zum Körper hin waschen, Hodensack zum Gesäß hin abtrocknen.", "kw": "Vorhaut|vorhaut; Eichel|eichel; zurückziehen|zurück/wieder vor/darüber; Paraphimose|paraphimose/einklemm"}, {"id": "P023", "deck": "p", "q": "Was hilft, wenn ein Mensch die Körperpflege ablehnt?", "a": "Ablehnung respektieren, den konkreten Hilfebedarf erkennen, zur Selbstständigkeit ermutigen, anbieten statt drängen, Zeit lassen und sanft berühren, loben, eine angenehme Umgebung schaffen, Gewohnheiten beachten, jeden Schritt ankündigen, an der unempfindlichsten Stelle beginnen, auf nonverbale Zeichen achten.", "kw": "respektieren|respekt/akzept; nicht drängen|dräng/anbiet/zeit; Gewohnheiten|gewohn/routine; informieren|inform/ankünd; loben|lob/bestärk/ermutig"}, {"id": "P024", "deck": "p", "q": "Wie kannst du mit Ekel in der Pflege umgehen?", "a": "Ekel ist normal. Ekelsituationen vorbeugen (zum Beispiel durch Prophylaxen und genug Flüssigkeit), sich schützen (Handschuhe, Schutzkleidung, frische Luft), sich bewusst auf die Tätigkeit konzentrieren, danach eine kurze Pause an der frischen Luft machen.", "kw": "vorbeugen|vorbeug/prophyl; Handschuhe|handschuh/schutz; frische Luft|luft/lüft; konzentrieren|konzentr/perspekt; Pause|pause/auszeit"}, {"id": "P025", "deck": "p", "q": "Wie schützt du das Schamgefühl eines Menschen?", "a": "Scham bewusst wahrnehmen, Eingriffe in die Intimsphäre ankündigen, Sichtschutz nutzen, den Körper nicht unnötig entblößen und den Intimbereich abdecken, Besucher hinausbitten, nicht ungefragt Schrank oder Nachttisch öffnen, den Menschen den Intimbereich so weit wie möglich selbst waschen lassen.", "kw": "ankündigen|ankünd/inform; Sichtschutz|sichtschutz/vorhang/wand; abdecken|abdeck/zudeck/entblöß; Besucher|besuch; selbst waschen|selbst"}, {"id": "P026", "deck": "p", "q": "Was ist Intertrigo und wie beugst du vor?", "a": "Wunde, gerötete Haut in Hautfalten durch Feuchtigkeit, Wärme und Reibung, oft mit Jucken oder Schmerz und Gefahr einer Pilz- oder Bakterieninfektion. Risiko: Übergewicht, Diabetes, Inkontinenz, starkes Schwitzen, Abwehrschwäche.\nProphylaxe: Hautfalten beobachten, lauwarm reinigen, gründlich abtrocknen, Kompressen einlegen, kein Puder, atmungsaktive, nicht zu enge Kleidung.", "kw": "Hautfalten|falte; Feuchtigkeit|feucht/nass/schwitz; Reibung|reib; abtrocknen|abtrock/trocken; Kompressen|kompress"}, {"id": "P027", "deck": "p", "q": "Welche Ziele hat die Mundpflege?", "a": "Eine gesunde, feuchte, gut durchblutete Mundschleimhaut, problemloses Kauen, eine geschmeidige Zunge, gesunde Zähne, funktionierende Speicheldrüsen und Wohlbefinden.", "kw": "Schleimhaut|schleimhaut/feucht; Kauen|kau; Zähne|zahn/zähne; Speichel|speichel; Wohlbefinden|wohl"}, {"id": "P028", "deck": "p", "q": "Erkläre die KAI-Technik und die Rot-Weiß-Methode beim Zähneputzen.", "a": "KAI: erst Kauflächen, dann Außenflächen, dann Innenflächen, mit kleinen kreisenden Bewegungen.\nRot-Weiß-Methode: Bürste am Zahnfleisch (rot) ansetzen und zum Zahn (weiß) hin abrollen, etwa viermal je Stelle. Erst außen, dann innen, zum Schluss die Kauflächen. Gut für die Pflege, weil man kaum zu viel Druck ausübt.", "kw": "Kauflächen|kaufl; Außenflächen|außen; Innenflächen|innen; Zahnfleisch|zahnfleisch/rot; abrollen|abroll/weiß"}, {"id": "P029", "deck": "p", "q": "Was ist bei Zahnbürste und Prothesenpflege wichtig?", "a": "Zahnbürste: kurzer Kopf, abgerundete Borsten, nach Gebrauch spülen, aufrecht trocknen lassen, spätestens nach drei Monaten wechseln.\nProthese: mindestens zweimal täglich reinigen, erst die obere, dann die untere herausnehmen, Einsetzen in umgekehrter Reihenfolge. Über Wasser oder einem Waschlappen reinigen, nie in Zellstoff einwickeln, Prothesenbecher mit Namen beschriften, Prothese regelmäßig tragen.", "kw": "drei Monate|monat/wechsel; trocknen|trock/aufrecht; zweimal täglich|zweimal/täglich; Zellstoff|zellstoff/einwickel/wegwerf; beschriften|beschrift/name"}, {"id": "P030", "deck": "p", "q": "Was ist Soor und wie beugst du vor?", "a": "Soor ist eine Pilzinfektion der Schleimhaut, meist durch Candida albicans, zum Beispiel im Mund. Gefährdet sind Menschen mit Abwehrschwäche, Antibiotikatherapie, Nahrungskarenz, Diabetes oder schlechter Mundpflege.\nProphylaxe: Mundhöhle mindestens einmal täglich ansehen, regelmäßige Mundpflege, ausreichend trinken, Veränderungen dokumentieren, Medikamente nur nach ärztlicher Anordnung.", "kw": "Pilz|pilz/candida; Schleimhaut|schleimhaut/mund; Abwehrschwäche|abwehr/immun; Antibiotika|antibiot; Mundpflege|mundpflege/zähne/inspiz/ansehen"}, {"id": "P031", "deck": "p", "q": "Was ist eine Parotitis und wie beugst du vor?", "a": "Eine Entzündung der Ohrspeicheldrüse. Sie entsteht, wenn zu wenig Speichel fließt, zum Beispiel bei Nahrungskarenz. Zeichen: Schwellung, Druckschmerz, Kauschmerz.\nProphylaxe: Speichelfluss anregen durch Kauen (Brotrinde, Kaugummi, Dörrobst), zuckerfreie Bonbons oder Eiswürfel lutschen, normales Essen fördern, Ohrspeicheldrüse massieren.", "kw": "Ohrspeicheldrüse|ohrspeichel/parotis; Speichel|speichel; Kauen|kau/brotrinde/kaugummi; lutschen|lutsch/bonbon/eis; Massage|massag"}, {"id": "P032", "deck": "p", "q": "Was bedeutet aktivierende Pflege?", "a": "Pflege, die Selbstständigkeit, Selbstbestimmung und Selbstwirksamkeit erhält und fördert. Sie nutzt die vorhandenen Fähigkeiten (Ressourcen) und übernimmt nur, was der Mensch nicht selbst kann. Man nennt sie auch Pflege mit den Händen in der Tasche. Gegenteil ist die verwahrende Pflege.", "kw": "Selbstständigkeit|selbstständ/selbständ; Selbstbestimmung|bestimm; Ressourcen|ressource/fähigkeit; nur übernehmen|übernehm/hände in der tasche/nicht kann"}, {"id": "P033", "deck": "p", "q": "Was ist Basale Stimulation?", "a": "Ein Konzept nach Andreas Fröhlich für Menschen mit stark eingeschränkter Wahrnehmung, Bewegung und Kommunikation. Durch gezielte Reize über Körper und Sinne werden Wahrnehmung und Kommunikation gefördert. Grundbereiche: somatisch (Körper und Haut), vestibulär (Gleichgewicht und Lage) und vibratorisch (Vibration). Pflegehandlungen können je nach Art aktivieren oder beruhigen.", "kw": "Wahrnehmung|wahrnehm; Fröhlich|fröhlich; somatisch|somat/haut/körper; vestibulär|vestib/gleichgew; vibratorisch|vibr"}]};
